(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Aang","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Shopkeeper! Appa's all rested up!"},{"a":"atlab_aang","t":"So... I guess it's time for farewells..."},{"a":"atlab_sokka","t":"Hey, cheer up! We can come back anytime!"},{"a":"atlab_aang","t":"You're right! Do you remember the way, Sokka?"},{"a":"atlab_sokka","t":"Uh... I wasn't paying attention..."},{"a":"atlab_sokka","t":"A-anyway! We've got super important Avatar business to get back to!"},{"a":"atlab_sokka","t":"C'mon Momo! We're leaving!"},{"a":"atlab_aang","t":"Momo! ...Momo?"},{"a":"atlab_aang","t":"You like it here, don't you? All right, fine."},{"a":"atlab_aang","t":"Shopkeeper, would you mind keeping an eye on Momo for a while?"},{"a":"atlab_aang","t":"I'll come back for you later, Momo. Promise!"},{"a":"atlab_aang","t":"Let's go, Sokka. Thanks for everything, Shopkeeper!"},{"a":"atlab_sokka","t":"Bye!"},{"a":"atlab_aang","t":"Come on, Appa! Yip yip!"}]},{"id":"atlab_aang_01","i":1,"title":"Fated Wrong Turn","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"inn","t":"Sorry kid, I didn't get all that. Mind repeating your story from the start?"},{"a":"atlab_aang","t":"Sorry! Let me start over!"},{"a":"atlab_aang","t":"I'm Aang, the Avatar."},{"a":"atlab_aang","t":"Me and my friends were traveling on my sky bison..."},{"a":"atlab_aang","t":"While flying, we must've taken a wrong turn, because we ended up here!"},{"a":"inn","t":"That huge ox outside? That thing flies?"},{"a":"atlab_aang","t":"Yes! His name is Appa. He's very friendly!"},{"a":"inn","t":"Looks pretty exhausted, too. You guys are being chased by someone, right?"},{"a":"atlab_aang","t":"Oh, um..."},{"a":"inn","t":"Hey, don't worry about it. I won't let anyone under my roof come to harm. Oscar's promise."},{"a":"inn","t":"Tell you what, how would you guys like to stay here for free?"},{"a":"atlab_aang","t":"For free? Really!?"},{"a":"inn","t":"Well for starters, it doesn't look like that weird money of yours will be worth anything here."},{"a":"inn","t":"I can't just let a bunch of kids sleep out in the streets now, can I?"},{"a":"atlab_aang","t":"T-thank you Mr. Oscar!"},{"a":"inn","t":"You look pretty capable, how about you go help my shopkeeper buddy in exchange?"},{"a":"atlab_aang","t":"Sure thing! Thank you so much!"}]},{"id":"atlab_aang_02","i":2,"title":"Firebending?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"inn","t":"Hey, Lilu! Come meet my new buddy here!"},{"a":"lilu","t":"Hi! I've never seen tattoos like yours before..."},{"a":"atlab_aang","t":"I'm Aang! I've never seen a hat like yours, either!"},{"a":"inn","t":"C'mon Aang, show her your trick!"},{"a":"atlab_aang","t":"You mean... this?"},{"a":"lilu","t":"H-how did you do that? I didn't sense any magic!"},{"a":"atlab_aang","t":"Airbending! I can also bend earth and water!"},{"a":"lilu","t":"Incredible! Hang on, let me take notes..."},{"a":"lilu","t":"Could it be Chi? I've never seen anyone do this before..."},{"a":"atlab_aang","t":"That's right! But not anyone can do it, you need to be born with the ability and learn to master it!"},{"a":"lilu","t":"You said you could bend air, earth and water... what about fire?"},{"a":"atlab_aang","t":"Ah... I... I haven't mastered firebending yet..."},{"a":"atlab_aang","t":"...I've had problems finding a firebending master to teach me."},{"a":"lilu","t":"Is that so? I know some fire magic!"},{"a":"lilu","t":"It's not quite the same, but you might like to see how it works!"},{"a":"atlab_aang","t":"Ah... sure. Thanks, Lilu."}]},{"id":"atlab_aang_03","i":3,"title":"The Last Airbender","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"elderowen","t":"Aang, my boy. How are you liking the city life?"},{"a":"atlab_aang","t":"Elder Owen! It's great! Thank you for your hospitality."},{"a":"elderowen","t":"It is nothing. But tell me, my boy, where are your parents?"},{"a":"atlab_aang","t":"Ah... I don't... have parents anymore."},{"a":"atlab_aang","t":"My family... all of the Air Nomads were killed by the Fire Nation."},{"a":"atlab_aang","t":"...I'm the only one left."},{"a":"elderowen","t":"Dear me! My condolences, poor child...."},{"a":"elderowen","t":"...If you have nowhere to return to, how about settling here with your friends?"},{"a":"elderowen","t":"I'm certain the city would be overjoyed to have you stay. You're quite popular already!"},{"a":"atlab_aang","t":"Thank you for the generous offer, Elder... but I can't accept."},{"a":"atlab_aang","t":"As we speak, Fire Lord Ozai is already planning his next move."},{"a":"atlab_aang","t":"When Sozin's Comet lights the sky again, the Fire Nation will conquer my world..."},{"a":"atlab_aang","t":"...The Earth Kingdom... the Water Tribes... They will suffer the same fate as the Air Nomads."},{"a":"atlab_aang","t":"As the Avatar, I'm the only one who can stop him! ...but I'm not ready."},{"a":"elderowen","t":"What a terrible burden for a child to bear..."},{"a":"elderowen","t":"No matter what, know that you have our city's full support."},{"a":"atlab_aang","t":"Thank you, Elder. You have all done so much for us already!"},{"a":"atlab_aang","t":"We'll be sure to pay you all a visit when this is all over!"}]},{"id":"atlab_aang_04","i":4,"title":"Sozin's Omen","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"mana","t":"Avatar. Our paths finally cross."},{"a":"atlab_aang","t":"Who are you? How do you know me?"},{"a":"mana","t":"The Avatar's presence shines like a beacon to the Third Eye."},{"a":"atlab_aang","t":"Oh, fortune telling... I'll pass!"},{"a":"mana","t":"You, who is many, yet not quite whole..."},{"a":"mana","t":"A fierce battle with the Lord of Fire awaits."},{"a":"atlab_aang","t":"Fire Lord Ozai... You know about him?"},{"a":"mana","t":"Under the Comet's gaze, land will be torn asunder, and the fields will be burned to ashes!"},{"a":"atlab_aang","t":"I know that! But what should I do?"},{"a":"mana","t":"The flow of fate cannot be broken."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"...But the brave can pull at the strings, and lead it astray."},{"a":"mana","t":"An unlikely ally and a fragile alliance may be the key."},{"a":"atlab_aang","t":"Thanks, fortune teller... I'll think about it."},{"a":"mana","t":"..."},{"a":"mana","t":"Be brave, Avatar. Stay true to yourself, and you shall overcome."}]}]},{"id":"argon","name":"Argon","chapters":[{"id":"argon_01","i":1,"title":"The King's Shadow","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"...And that's when I slashed the Troublin with my sword! Pow!"},{"a":"elderowen","t":"Ho ho! Quite the tale, Argon!"},{"a":"elderowen","t":"Ah, the fire of youth..."},{"a":"elderowen","t":"I must say, it's very nice of you to accompany this old man on his morning walk."},{"a":"argon","t":"Don't mention it! If I am to become a knight someday, I must help people in need!"},{"a":"elderowen","t":"Just like your father, eh? I'm sure you'll make a fine knight, my boy."},{"a":"elderowen","t":"Why, perhaps you could even work as the King's royal guard!"},{"a":"elderowen","t":"Speak of the devil, there he is at the market! Why not go ask him?"},{"a":"argon","t":"YOUR MAJESTY! I've come to offer you my services as a knight!"},{"a":"king","t":"W-what's the meaning of this!? Sia, please handle this commoner!"},{"a":"sia","t":"Of course, my King."},{"a":"sia","t":"Well, young man? What is it?"},{"a":"argon","t":"Wow! I, uh..."},{"a":"argon","t":"I'm knight! I want to become an Argon!"},{"a":"argon","t":"No, wait a minute..."},{"a":"sia","t":"You certainly have guts!"},{"a":"sia","t":"If you're so determined, come see me in the castle's courtyard next week."},{"a":"sia","t":"Train hard until then! I would not tolerate a slacker among the King's knights..."}]},{"id":"argon_02","i":2,"title":"Training Montage","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Argon, what are you doing out here?"},{"a":"argon","t":"Training hard! I've finally got my chance at becoming a knight for the King!"},{"a":"lilu","t":"The King? ...Or his mysterious advisor, Sia?"},{"a":"argon","t":"Is that her name? It's beautiful, too!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Gah! No! Only the King matters!"},{"a":"argon","t":"I must become a knight! Nothing else matters!"},{"a":"lilu","t":"Right... Here, let me heal your wounds."},{"a":"argon","t":"Thanks- ouch! This spell stings!"}]},{"id":"argon_03","i":3,"title":"Two Sides of a Coin","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"Alright! Sia will show up any moment now!"},{"a":"argon","t":"My training has paid off, I'm ready!"},{"a":"argon","t":"...But I'm still way too nervous..."},{"a":"argon","t":"Oh! Hi there! You, in the bushes!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Are you here to become a knight too?"},{"a":"argon","t":"Sia will be here soon! There's no need to hide, she's pretty nice!"},{"a":"yami","t":"Sia...!"},{"a":"yami","t":"I need to leave. Farewell."},{"a":"argon","t":"W-wait!"},{"a":"argon","t":"Woah! Smoke bomb!?"},{"a":"argon","t":"What a strange girl..."},{"a":"sia","t":"Young man, who are you talking to?"},{"a":"argon","t":"Ah, Sia! Just a shy passerby! Pay it no mind!"},{"a":"sia","t":"...I see. Well then, it seems your resolve has not wavered."},{"a":"sia","t":"Are you ready to risk your life as one of the King's knights?"},{"a":"argon","t":"You bet! I-I mean, of course! I will make my father proud!"},{"a":"sia","t":"Good. For your first assignment, I have an important event coming up..."}]},{"id":"argon_04","i":4,"title":"Empty-Handed","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Surely you jest!"},{"a":"sia","t":"You've cornered the assassin... and failed to stop her."},{"a":"sia","t":"Not only that, you're saying you LET HER GO because you think she's a good person!?"},{"a":"argon","t":"..."},{"a":"sia","t":"What nonsense is this?"},{"a":"sia","t":"You DO realize that this assassin tried to kill our King - the very man you have sworn to protect?"},{"a":"sia","t":"Such an incident endangers much more than your feeble mind can understand."},{"a":"sia","t":"Ugh... I suppose the King has the final say about the termination of his knights..."},{"a":"sia","t":"...But don't expect me to speak highly of you. Dismissed."},{"a":"argon","t":"..."},{"a":"argon","t":"Oh man..."},{"a":"argon","t":"Sorry, dad."}]},{"id":"argon_a","i":4,"title":"The Tower of Titans","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"elderowen","t":"The Tower of Titans, eh?"},{"a":"lilu","t":"Please tell us all about it!"},{"a":"argon","t":"I heard some Heroes whisper about it, but no one has ever seen it..."},{"a":"elderowen","t":"Indeed, the Tower of Titans is a mythical place. Nobody really knows if it truly exists."},{"a":"elderowen","t":"Stories say it appears out of thin air, challenging the mightiest Heroes to climb its many floors..."},{"a":"elderowen","t":"...Before suddenly disappearing, wiping clean the memories of anyone who may have seen it."},{"a":"argon","t":"W-wiping memories!?"},{"a":"lilu","t":"That's strange... where would the legend come from, then?"},{"a":"argon","t":"Right! Some people would need to remember!"},{"a":"elderowen","t":"It is said that those who overcome the Titan's challenge are deemed worthy by the Tower."},{"a":"elderowen","t":"These Heroes return... changed from the experience, and retain their memories."},{"a":"elderowen","t":"More accurately, a part of them remains in the Tower, and a part of the Tower remains with them."},{"a":"elderowen","t":"...That will be all for today's story time. Thank you for listening to this old man's tales."},{"a":"lilu","t":"Wow! I wonder if it truly exists?"},{"a":"argon","t":"Yeah! I'd love to explore a dungeon like that!"},{"a":"lilu","t":"But one thing seems strange... How does Elder Owen know all this?"},{"a":"argon","t":"...!"}]},{"id":"argon_05","i":5,"title":"Knight Errant","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"Sigh..."},{"a":"steel","t":"If it isn't Argon! How are you doing today?"},{"a":"argon","t":"Oh, hi Brohm... Any jobs for me?"},{"a":"steel","t":"Nothing today, sir Knight! What's got you down?"},{"a":"argon","t":"I'm just Argon now. I've... lost my title."},{"a":"steel","t":"Oh, that stings..."},{"a":"steel","t":"\"Whatever happens, you need to stay positive! You'll pull through!\""},{"a":"steel","t":"I'm sure your luck will turn soon enough!"},{"a":"argon","t":"Right... Thanks, Brohm."},{"a":"argon","t":"I'll be... hanging around the Town Square until then."},{"a":"argon","t":"Sigh..."}]},{"id":"argon_b","i":5,"title":"Are we the Titans?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"lilu","t":"Good morning... Argon."},{"a":"argon","t":"Yawn... Mornin'."},{"a":"lilu","t":"...You're feeling it too, aren't you?"},{"a":"argon","t":"Yeah, I'm beat! I feel like I've been questing all night!"},{"a":"lilu","t":"Look, your shield is all chipped, too!"},{"a":"argon","t":"Huh? You're right! I could've sworn it was sparkling clean yesterday..."},{"a":"lilu","t":"Argon... Do you think...?"},{"a":"polonia","t":"Ahoy! Are any of ye fine landlubbers on the market for some <c1>Juggernaut Greaves</c1>?"},{"a":"lilu","t":"No... especially not twenty of them! Where did you get all that!?"},{"a":"polonia","t":"Hah! Funny ye ask. I have no clue."},{"a":"polonia","t":"I think I might be lootin' in me sleep. Must be me pirate soul actin' up, arr."},{"a":"lilu","t":"That weird pirate lady too..."},{"a":"lilu","t":"...Did we all challenge the Tower and had our memories wiped...?"},{"a":"argon","t":"That means we weren't strong enough..."},{"a":"argon","t":"I'll train hard for next time! Just you see!"}]},{"id":"argon_06","i":6,"title":"Second Light","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"And so, that... \"Knight\", had your assassin at his mercy..."},{"a":"sia","t":"...Yet decided to let her go, believing her to be a good person!"},{"a":"king","t":"A fascinating tale! This new knight appears to be a promising fellow!"},{"a":"sia","t":"With all due respect, my King..."},{"a":"sia","t":"This man failed to stop your assassin, on account of a mere gut feeling."},{"a":"king","t":"The hallmark of a <c1>Paladin</c1>, wouldn't you think?"},{"a":"sia","t":"Excuse me?"},{"a":"king","t":"To have your nemesis at your mercy, yet seeing beyond mere strife and conflict..."},{"a":"king","t":"...Then letting them go, so certain of their redemption that you are willing to put your title on the line."},{"a":"king","t":"A tremendous act of bravery and benevolence!"},{"a":"sia","t":"I... must admit I did not consider this perspective, my King."},{"a":"sia","t":"But the kingdom has not seen an aspiring Paladin in decades..."},{"a":"sia","t":"Shall I summon the knight council to debate the matter?"},{"a":"king","t":"Nonsense! I shall handle the formalities myself."},{"a":"sia","t":"As you wish, my King. I shall prepare an escort immediately."},{"a":"king","t":"There is no need. I shall be as discreet as a mouse!"}]},{"id":"argon_07","i":7,"title":"The Inconspicuous King","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"king","t":"Stand aside, peasants! An average laborer walks among you!"},{"a":"tavern","t":"Ah, King Reinhold! It's been a while. Shall I tap open a keg of Ambrosia?"},{"a":"king","t":"Shhh! I am undercover today! Pay me no mind!"},{"a":"tavern","t":"Yes, of course! How silly of me!"},{"a":"king","t":"You there! Hiding behind the counter!"},{"a":"argon","t":"Ah! Uh, sorry, your Majesty. I'll get out of the way..."},{"a":"king","t":"Nonsense! A Paladin-to-be is more than worthy of sitting next to my radiant self!"},{"a":"argon","t":"Sitting next to... Paladin!?"},{"a":"king","t":"Correct! In my infinite wisdom, I've sensed great potential within you!"},{"a":"king","t":"Despite your... unusual methods, your heart is true and your sense of justice is... admirable!"},{"a":"king","t":"The kingdom has thus deemed you fit to undertake the Paladin Trial!"},{"a":"argon","t":"A Paladin Trial... Wow!"},{"a":"argon","t":"I know all about them! Each is unique and decided by the Paladin itself..."},{"a":"argon","t":"It must be a dangerous task, like slaying a dragon... or destroying a dangerous artifact..."},{"a":"king","t":"Indeed! Any sufficiently brave and selfless deed done for the sake of the kingdom will do!"},{"a":"argon","t":"I understand! Thank you, your Majesty! You won't regret it!"},{"a":"king","t":"Of course not, I'm always right!"},{"a":"king","t":"...Now then, since I am already undercover..."},{"a":"king","t":"You there! Old man! Teach me how to play cards!"},{"a":"master","t":"Cards, eh? Old Theodore only plays with high stakes..."}]},{"id":"argon_08","i":8,"title":"Rekindled","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Argon! What's the rush?"},{"a":"argon","t":"Lilu, I'm going to be a Paladin!"},{"a":"lilu","t":"A Paladin! T-that's amazing, Argon! How...?"},{"a":"argon","t":"The King told me to face a trial! That's the only way to truly be worthy of the title of Paladin."},{"a":"lilu","t":"A trial... Do you know what you will do?"},{"a":"argon","t":"..."},{"a":"argon","t":"Oh no! I have no clue!"},{"a":"argon","t":"It has to be something of epic and glorious proportions..."},{"a":"lilu","t":"But Argon, you are glorious! You've defeated monsters far and wide..."},{"a":"argon","t":"Sure, but it has to be something more..."},{"a":"argon","t":"I've heard there are feathered demons at Bleakspire Peak, maybe that would do it...."},{"a":"lilu","t":"Well whatever it is, I'm sure you're up for it!"},{"a":"argon","t":"Thanks, Lilu... Even when I was no longer a Knight, you kept believing in me..."},{"a":"lilu","t":"Oh! Th-that was nothing!"},{"a":"lilu","t":"Anyway! You'll need help in your quest! I'll prepare a few healing scrolls for you!"},{"a":"argon","t":"Amazing! Onward!"}]},{"id":"argon_09","i":9,"title":"Bleakspire Clash (Argon)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"Ugh... this place sucks!"},{"a":"argon","t":"All this climbing and no Harpies in sight... I even got ambushed by assassins!"},{"a":"argon","t":"...They kinda looked like that Ninja girl, didn't they?"},{"a":"argon","t":"Good thing Lilu gave me these healing scrolls, whew!"},{"a":"argon","t":"Guess I'll take a break here."},{"a":"argon","t":"...Huh?"},{"a":"yami","t":"You again."},{"a":"argon","t":"T-the King's assassin!"},{"a":"argon","t":"This must be fate. A bounty even greater than a Harpy!"},{"a":"yami","t":"...Bring it on. I'll kill you where you stand."}]},{"id":"argon_10a","i":10,"title":"Triumphant Return","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"King Reinhold! Quest complete!"},{"a":"king","t":"Wonderful! What manner of foul beast have you slain?"},{"a":"argon","t":"Um... about that."},{"a":"yami","t":"...Hi."},{"a":"king","t":"W-w-what's the meaning of this!?"},{"a":"sia","t":"Guards! Arrest them both!"},{"a":"argon","t":"Woah! Hold on! She's turned over a new leaf!"},{"a":"king","t":"Is-is that so?"},{"a":"yami","t":"I've come to... apologize."},{"a":"sia","t":"My King, surely you wouldn't believe..."},{"a":"argon","t":"I can vouch for her! Knight's honor!"},{"a":"king","t":"Very well! I shall hear her plea!"},{"a":"sia","t":"Ugh... I feared this would happen."},{"a":"sia","t":"Guards! Bring reinforcements and watch her every move!"},{"a":"sia","t":"Argon, please wait outside while we discuss with this... intruder."},{"a":"argon","t":"At once!"},{"a":"argon","t":"(...Did I make a huge mistake?)"}]},{"id":"argon_10b","i":11,"title":"Redemptor","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"Ugh... I did not need this headache today."},{"a":"argon","t":"Lady Sia! How did it go?"},{"a":"sia","t":"...Against all odds, King Reinhold is willing to forgive his own would-be assassin."},{"a":"sia","t":"While I am not so trustful, she did share valuable intel on her Azuman order."},{"a":"argon","t":"T-then this means...!"},{"a":"sia","t":"Yes, we'll accept her surrender and apology."},{"a":"sia","t":"She is currently under medical care due to starvation, but she should make a full recovery."},{"a":"sia","t":"As for you, Paladin Argon..."},{"a":"argon","t":"P-paladin!"},{"a":"sia","t":"Yes, It is something to vanquish a threat, but to redempt a sworn enemy of the kingdom..."},{"a":"sia","t":"It appears King Reinhold was right about you, after all."},{"a":"sia","t":"Now go and celebrate, Paladin. I'm sure you'll be very busy, very soon!"},{"a":"argon","t":"I will! Thank you!"},{"a":"argon","t":"Dad... I hope you're proud."}]},{"id":"argon_epilogue","i":12,"title":"Epilogue","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"P-paladin!? You did it, Argon!"},{"a":"argon","t":"I really thought I blew it for a moment there..."},{"a":"argon","t":"But dad was right. All I need to do is follow my heart!"},{"a":"lilu","t":"Ah... but does that mean you'll be sent away on campaign overseas?"},{"a":"argon","t":"Not yet. Lady Sia hopes I can teach Heroes to become Paladins."},{"a":"lilu","t":"Ah! That's a relief! ...Though I have a hard time imagining you as a teacher."},{"a":"lilu","t":"Won't you be busy with super important Paladin quests?"},{"a":"argon","t":"I'll do my best! The kingdom is counting on me!"},{"a":"tavern","t":"Hi there, noble Paladin!"},{"a":"tavern","t":"Brohm told me he was looking for some more smelting gloves!"},{"a":"argon","t":"Yes! Right away!"},{"a":"lilu","t":"...Some things never change, huh?"},{"a":"tavern","t":"Not our Argon, that's for sure."}]},{"id":"argon_c","i":13,"title":"Set in Stone","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"The potion... didn't work, did it?"},{"a":"lilu","t":"Sigh... We worked so hard on it, too..."},{"a":"lilu","t":"Sorry, Argon. I wasn't good enough... I hope it's not too uncomfortable in there."},{"a":"elderowen","t":"Hmm... dire news indeed."},{"a":"lilu","t":"We're not out of options yet, but..."},{"a":"lilu","t":"...It's really tough when he's not around with us."},{"a":"elderowen","t":"The city certainly feels empty without him, doesn't it?"},{"a":"lilu","t":"...Like a birthday party with no friends."},{"a":"lilu","t":"...Moping around won't bring him back any faster. I'll get back to it."},{"a":"lilu","t":"Maybe we can ask Donovan for help."},{"a":"lilu","t":"It'll cost us, but we can pool our money!"},{"a":"lilu","t":"I know you're not going anywhere but... hang in there! We'll save you!"},{"a":"argon_stone","t":"..."}]}]},{"id":"ashley","name":"Ashley","chapters":[{"id":"ashley_01","i":1,"title":"The Unusual Samurai","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"A real Samurai...! I can't wait!"},{"a":"argon","t":"Lady Samurai! I'm Argon! Knight-in-train-"},{"a":"ashley","t":"Oi. I'm Ashley. What's up?"},{"a":"argon","t":"O-oi?"},{"a":"tavern","t":"Feet off the table, please!"},{"a":"ashley","t":"Tch. Alright."},{"a":"ashley","t":"Well? What'd you need?"},{"a":"argon","t":"Uh... aren't Samurai usually more like, orderly and stuff?"},{"a":"ashley","t":"Huh? Yeah, the guys back home were pretty stuffy about it."},{"a":"ashley","t":"I'm free now. Just a Ronin. A Samurai without a lord."},{"a":"argon","t":"I see... Oh, right!"},{"a":"argon","t":"I had a quest planned with Lilu at the Haunted Castle but..."},{"a":"argon","t":"Something came up at the Training Hall! Can you fill in for me?"},{"a":"ashley","t":"Sure. But you owe me, knight boy."}]},{"id":"ashley_02","i":2,"title":"Armed & Ready","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"ashley","t":"You're Lilu, yeah?"},{"a":"lilu","t":"Yes, that's right! Pleased to meet you!"},{"a":"ashley","t":"Right then, let's get going."},{"a":"lilu","t":"W-wait! Hold on!"},{"a":"lilu","t":"We still haven't made preparations! Potions, rations, and-"},{"a":"ashley","t":"Whatever, we don't need any of that."},{"a":"ashley","t":"We live or we die. No in-between."},{"a":"lilu","t":"That's... no! That's too reckless!"},{"a":"ashley","t":"I'm going. This way, right?"},{"a":"lilu","t":"No! That's the Howling Woods..."},{"a":"argon","t":"Um... Good luck?"}]},{"id":"ashley_03","i":3,"title":"Life's Edge","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"ashley","t":"Is that all you monsters got? BRING IT!"},{"a":"lilu","t":"Ashley! Please slow down! My healing can't keep up!"},{"a":"ashley","t":"This... is... NOTHING!!!"},{"a":"ashley","t":"Whew... good scrap, yeah?"},{"a":"lilu","t":"Are you kidding!? You almost died!"},{"a":"lilu","t":"It's no wonder you lost your arm if you keep acting like this!"},{"a":"ashley","t":"Oi. That was different."},{"a":"ashley","t":"That mistake... I won't repeat."},{"a":"lilu","t":"Hmph. I'm not using anesthetics for this healing."},{"a":"lilu","t":"This is your own fault. Brace up."},{"a":"ashley","t":"Haha... hah... I can take it..."},{"a":"ashley","t":"Ouch! Ow ow ow-"}]},{"id":"ashley_a","i":4,"title":"Familiar Feeling","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"ashley","t":"Oi. What's with all these tiny monsters around here?"},{"a":"elven","t":"These would be my dear familiars. Welcome."},{"a":"elven","t":"Worthy Champions can come and adopt one as a faithful companion."},{"a":"ashley","t":"Oh. Pets, yeah? I get it."},{"a":"ashley","t":"Alright. You, green guy. I'll call you <c1>Tricky</c1>. Come with me."},{"a":"ashley","t":"You're cute, <c1>Snowball</c1>. I'll carry you."},{"a":"elven","t":"Ah... I'm afraid that-"},{"a":"ashley","t":"Yikes, that's one ugly bird!"},{"a":"ashley","t":"I'll call you <c1>Sparrow</c1>. You can come too."},{"a":"elven","t":"...I see. Have fun, you all."}]},{"id":"ashley_04","i":5,"title":"Quest Failed Successfully","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"How did yesterday's quest go? Lilu looked pretty upset..."},{"a":"ashley","t":"I made it back in one piece. Sadly."},{"a":"argon","t":"Huh!? Isn't that a good thing?"},{"a":"king","t":"Greetings, commoners! Feel free to gaze upon my splendor!"},{"a":"ashley","t":"Ah, lord King sir! Ashley reporting for duty!"},{"a":"king","t":"Now that is a fine example of a soldier! Keep up the good work!"},{"a":"ashley","t":"Yes sir! Thank you sir!"},{"a":"tavern","t":"Sorry Reinhold, your vintage hasn't arrived yet."},{"a":"king","t":"Very well! I shall return on the morrow!"},{"a":"argon","t":"What was that about?"},{"a":"ashley","t":"Oh, uh. Used to serve a lord. Old habits kicked in."},{"a":"argon","t":"Cool! Tell me about it!"},{"a":"ashley","t":"No."}]},{"id":"ashley_05","i":6,"title":"Turning Tale","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"ashley","t":"...And then I told the guy..."},{"a":"ashley","t":"\"Armed and ready? Well, you could say I'm ready!\""},{"a":"argon","t":"Hahaha!"},{"a":"argon","t":"...But Ashley, about that lord you mentioned earlier..."},{"a":"ashley","t":"Aaaaah man... ya really ain't letting up. Fine"},{"a":"ashley","t":"...Samurai have a lord, a Daimyo. We serve and protect him with our lives."},{"a":"argon","t":"Very honorable!"},{"a":"ashley","t":"One regular day, he's having lunch as usual..."},{"a":"ashley","t":"Then suddenly, boom. Ninjas. All over the room. All... all after my master's head."},{"a":"ashley","t":"We fought hard. Wasn't the first time. But..."},{"a":"ashley","t":"Took a bad hit. Lost my arm."},{"a":"ashley","t":"Then I-...I ran. Left him to die."},{"a":"argon","t":"Ashley..."},{"a":"ashley","t":"...RAAAAAAAH!!! I should've just died back there!"},{"a":"ashley","t":"...Naya, swing me another one."},{"a":"tavern","t":"You've had quite enough today, Ashley."},{"a":"ashley","t":"Fine. S'alright. I've had my fill."},{"a":"ashley","t":"Right then. Argon, go tell Lilu Ashley's about to go on a really dangerous quest."},{"a":"argon","t":"Huh? Right now!?"},{"a":"ashley","t":"You bet. I'm headed for... let's say the Aurora Caves. Better hurry!"}]},{"id":"ashley_06","i":7,"title":"An Eye for an I","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"ashley","t":"...Ninja girl. You been eavesdropping?"},{"a":"yami","t":"...Some. Shall we take it outside?"},{"a":"ashley","t":"Hah! Ain't in the mood for a fight."},{"a":"yami","t":"My clan did this to Lord Kusunoki. I am an outcast, but perhaps my apologies-"},{"a":"ashley","t":"Thanks, but you don't have to. It's not you that I hate. It's me."},{"a":"yami","t":"I understand... Perhaps more than you can imagine."},{"a":"yami","t":"But even with your honor in tatters, you still have much to live for."},{"a":"yami","t":"You have friends here. A city as a family. Pets that you cherish."},{"a":"yami","t":"...But if that is not enough, I can offer you a honorable duel to the death."},{"a":"ashley","t":"A free assassination from a Ninja? You spoil me."},{"a":"ashley","t":"Thanks, but I'll pass. I'll consider it, though."},{"a":"yami","t":"As you wish."}]},{"id":"ashley_07","i":8,"title":"One Last Fight","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Huff... Huff... Ashley's not here..."},{"a":"lilu","t":"Did she get lost again...?"},{"a":"lilu","t":"No... wait. Did I get tricked?"},{"a":"ashley","t":"I thought I was headed for the Cinderlake Volcano..."},{"a":"ashley","t":"Whatever, good enough."},{"a":"ashley","t":"Alriiiiiight! Wake up, ya cretins! Ashley's here!"},{"a":"monster_Grotto_Mob","t":"Human is... drunk?"},{"a":"ashley","t":"No meddling healer today, just me and a deathwish! Ain't stopping 'till I'm dead!"},{"a":"ashley","t":"Whatever happens, I win! So, who's first?"},{"a":"monster_Ruins_Mob","t":"Grah! Bring it!"},{"a":"ashley","t":"That's the spirit!"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"priest","t":"O Goddess... is this the place?"},{"a":"priest","t":"Dear me, what a bloodbath."},{"a":"monster_Grotto_Mob","t":"Hee hee hee."},{"a":"priest","t":"Pardon me, monsters. Please allow me to retrieve my companion."},{"a":"monster_Grotto_Mob","t":"No way! NO way! She messed us up! That Samurai's dead as doornails!"},{"a":"priest","t":"She lives still. Our Ashley is tougher than this."},{"a":"monster_Ruins_Mob","t":"Eh? Then I better finish the job!"},{"a":"priest","t":"You will do no such thing."},{"a":"monster_Grotto_Mob","t":"Hee hee hah! What're gonna DO? Heal us?"},{"a":"priest","t":"You leave me no choice. May Goddess Asthea forgive you..."},{"a":"priest","t":"Because I won't."}]},{"id":"ashley_09","i":10,"title":"Bedrest Duress","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"ashley","t":"...Ugh..."},{"a":"priest","t":"You've finally come to."},{"a":"ashley","t":"Huh? Dammit... not you too. How'd... you find me?"},{"a":"priest","t":"It seems the Goddess cares for you. I was sent in her stead."},{"a":"ashley","t":"Damn... C'mon doc, just let me die."},{"a":"priest","t":"If that is truly your wish."},{"a":"ashley","t":"Sheesh... finally..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"...Then why are you still HEALING me?"},{"a":"priest","t":"Despite your words, it seems you still wish to live."},{"a":"priest","t":"Healing magic simply accelerates your life force. If you truly wanted to die, I could do nothing to save you."},{"a":"ashley","t":"Is that... so..."},{"a":"priest","t":"...Rest for now. You have much to think about."}]},{"id":"ashley_10","i":11,"title":"A Time to Think","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"You're back! Lilu's been looking all over for you!"},{"a":"argon","t":"...You're looking a bit messed up, too."},{"a":"ashley","t":"Don't mind it, I got patched up. Got an earful, too."},{"a":"argon","t":"From Freyja? That's hard to imagine."},{"a":"ashley","t":"Yeah. She told me to start thinkin'. So I'm thinkin'."},{"a":"tavern","t":"Thinking? That's new!"},{"a":"ashley","t":"Quit it."},{"a":"ashley","t":"...is what I'd like to say, but you're right."},{"a":"ashley","t":"Been stuck on the past so long, I forgot to think at all."},{"a":"argon","t":"Think about what?"},{"a":"ashley","t":"Hmm. Lotsa things."},{"a":"ashley","t":"Without me noticing, it seems I picked up a lot of things I cared about."},{"a":"ashley","t":"The city. The people. The shopkeep. You too, knight boy."},{"a":"ashley","t":"It only took several brushes with death to notice. Guess I'm slow on the uptake, heh."},{"a":"argon","t":"I'm honored, miss Samurai!"},{"a":"ashley","t":"Still a Ronin here. Don't expect that to change anytime soon."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Epilogue","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"ashley","t":"Yo, Lilu. I'm headed on another quest. Wanna come with?"},{"a":"lilu","t":"Hmph! So you can send me to the wrong location again?"},{"a":"lilu","t":"Or throw yourself at the monsters so recklessly that I have to stitch you back together?"},{"a":"ashley","t":"...Nah, I'm a changed woman now. I'll go easy, one hand behind my back."},{"a":"lilu","t":"Hmm... if you say so."},{"a":"lilu","t":"Wait a minute..."},{"a":"ashley","t":"Hah hah! Juuust kidding."},{"a":"ashley","t":"If you've got my back, I got yours."},{"a":"lilu","t":"Sounds good! But this time, promise me."},{"a":"lilu","t":"If things get too hairy... we retreat. YOU retreat."},{"a":"ashley","t":"It's a promise. Ronin honor, for what it's worth."},{"a":"ashley","t":"We have a home to return to, after all."}]}]},{"id":"bjorn","name":"Bjorn","chapters":[{"id":"bjorn_01","i":1,"title":"Dad's Home","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"bjorn","t":"Hi kids! Dad's home!"},{"a":"steel","t":"Dad!"},{"a":"wood","t":"...Dad."},{"a":"bjorn","t":"What's with the long face, Gorza?"},{"a":"wood","t":"You've been gone for months!"},{"a":"bjorn","t":"That's the Ranger's life! The great outdoors, far away from home."},{"a":"wood","t":"Pfft. It wouldn't hurt to stop by more often."},{"a":"bjorn","t":"I wish I could, but the Cinderlake Volcano tends to keep a man busy!"},{"a":"wood","t":"The Volcano? I thought you said you were investigating Bleakspire Peaks..."},{"a":"bjorn","t":"...Did I?"},{"a":"bjorn","t":"I guess I got it mixed up! Har har!"},{"a":"bjorn","t":"Anyway, I brought souvenirs for you two! Come take a look!"},{"a":"steel","t":"Oh! I hope there's a Crushy Plushie!"}]},{"id":"bjorn_a","i":1,"title":"Best Bud Bamham","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"bjorn","t":"Hey kids, you mind watching over Bamham for a bit?"},{"a":"wood","t":"That nasty boar? Not a chance. Keep him with you."},{"a":"steel","t":"No offense dad, but he's kind of... crazy?"},{"a":"bjorn","t":"Aw, don't say that! He's cute as a button!"},{"a":"wood","t":"Dad, he goes on a murderous rampage whenever you set him down."},{"a":"bjorn","t":"That time was an accident. He just got a lil' bit too excited."},{"a":"wood","t":"What about all the other times?"},{"a":"bjorn","t":"Those were... also accidents. Baby Bamham wouldn't hurt a fly!"},{"a":"wood","t":"He would, and he'd definitely enjoy it too."},{"a":"wood","t":"Look, dad, you're better off carrying that thing with you when you're in town."},{"a":"steel","t":"...For everyone's safety."},{"a":"bjorn","t":"Alright, alright. I get it. It's ok Bamham, I love you."},{"a":"bjorn","t":"Woah woah woah! Steady Bamham!"}]},{"id":"bjorn_02","i":2,"title":"Bjorn's Grocery Run","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"bjorn","t":"Thanks for the warm welcome, everyone! It's good to be back!"},{"a":"elderowen","t":"We are relieved to see you return safely. After you'd been gone for months, we feared the worst..."},{"a":"bjorn","t":"Sorry, sorry! That's just how the Ranger's life tends to be! Har har!"},{"a":"oils","t":"Knowing you, you must already be thinking about your next expedition!"},{"a":"bjorn","t":"Har har! You got me! We're leaving tomorrow at dawn, even!"},{"a":"oils","t":"Never change, Bjorn. I'll be sure to watch over Brohm and Gorza while you're gone."},{"a":"oils","t":"...If it's on the way, would you mind gathering a few Glow Shrooms for me?"},{"a":"bjorn","t":"Of course not! It's no trouble at all!"},{"a":"elderowen","t":"Oh... my back's been acting up lately. If you could find some Icy Pearls...?"},{"a":"bjorn","t":"It's barely a detour. I'll be on the lookout , Elder."},{"a":"engineer","t":"Oh! Bjorn! I'd like some Rustwyrm Scales for my next experiment, if you're able!"},{"a":"bjorn","t":"Of course, of course. Noted!"},{"a":"bjorn","t":"Whew...! Guess we'd better pack extra bags, Bamham!"}]},{"id":"bjorn_03","i":3,"title":"All That Litters is Gold","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"bjorn","t":"Hmm... You smell what I'm smelling, Bamham?"},{"a":"bjorn","t":"That's right, metal. Littering, most likely. C'mon Bam, find and fetch it!"},{"a":"bjorn","t":"Good boy, let me see here..."},{"a":"bjorn","t":"Huh. That's a strange device. I don't think it was left behind by accident..."},{"a":"bjorn","t":"Bet you that if I pull that crank here a bit..."},{"a":"bjorn","t":"Hmm... yes, exactly as I suspected."},{"a":"bjorn","t":"...It breaks. I guess we didn't learn that much, did we? Har har!"},{"a":"bjorn","t":"But I think we've got our lead. We've been looking around for months, and this thing wasn't there last time."},{"a":"bjorn","t":"Better head back and ask a pro. You know I'm no good with technology!"}]},{"id":"bjorn_04","i":4,"title":"Unknown Beacon","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"engineer","t":"What a strange piece! I've never seen anything like it."},{"a":"engineer","t":"It seems to combine both magic and science to act as some sort of... beacon? Radar?"},{"a":"engineer","t":"You said it was broken when you found it?"},{"a":"bjorn","t":"Yeah. What a stroke of bad luck, right? Har har!"},{"a":"engineer","t":"That's a shame. I can't really say more other than this: it definitely sends out some kind of information."},{"a":"engineer","t":"Tell you what, if you give me a minute, I can make you a device to help you find more of these... \"Magic Beacons\"."},{"a":"bjorn","t":"Great! You ready to head back out there, Bamham?"},{"a":"bjorn","t":"We don't know what these things are... but it can't be good."},{"a":"bjorn","t":"It's our job to find out who's behind this!"},{"a":"engineer","t":"Good luck! And... be careful when handling mysterious technology!"}]}]},{"id":"donovan","name":"Donovan","chapters":[{"id":"donovan_01","i":1,"title":"Original Recipe","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"herbalist","t":"Welcome to the Maribel Medicine Emporium! How can I help you?"},{"a":"donovan","t":"Lady Maribel, was it? I would like to personally commend your latest creation."},{"a":"donovan","t":"As the inventor of the Potion of Renewal, your modified blueprint is nothing short of genius!"},{"a":"donovan","t":"The simple addition of a dash of Mistpeak Bloom is a terrific improvement!"},{"a":"herbalist","t":"Wait a minute... you mean you're THE Donovan? No way!"},{"a":"herbalist","t":"The Potion of Renewal blueprint was invented roughly 700 years ago..."},{"a":"herbalist","t":"Even as an elf, you don't look a day over 150!"},{"a":"donovan","t":"You are too kind, Lady Maribel."},{"a":"donovan","t":"Let's just say that not all of my blueprints are commercially available..."},{"a":"donovan","t":"But I'm certain a master alchemist such as yourself would have no trouble learning them."},{"a":"donovan","t":"Now then, shall I take a look at some of that Mistpeak Bloom?"}]},{"id":"donovan_02","i":2,"title":"Land of Plenty","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"donovan","t":"Fascinating... Even the common apples around these parts are of excellent quality."},{"a":"donovan","t":"How could this be, I wonder...?"},{"a":"lilu","t":"If someone could explain it, it would be Juniper!"},{"a":"lilu","t":"Oh, sorry! I didn't mean to intrude in your conversation with that... tree."},{"a":"donovan","t":"Ah, a young lady in a broad brimmed hat and her loyal owl..."},{"a":"donovan","t":"You must be Miss Lilu, no doubt."},{"a":"lilu","t":"That's right! And you, Sir Donovan, obviously need no introduction!"},{"a":"donovan","t":"I've heard much about the prized young pupil of this city. The pleasure is all mine."},{"a":"donovan","t":"Now then, Miss Lilu. You were saying...?"},{"a":"lilu","t":"Oh yes! Juniper is always talking about how much the land around the city is teeming with life..."},{"a":"lilu","t":"It's part of the reason she enjoys gardening here so much, she says."},{"a":"lilu","t":"In any case, I was on my way to the Aurora Caves. Nice meeting you, Sir Donovan!"},{"a":"donovan","t":"May we meet again soon."},{"a":"donovan","t":"Hmm... Perhaps this young lady is onto something..."},{"a":"donovan","t":"Kern... depleted? Everything seems much more vibrant in this kingdom."},{"a":"donovan","t":"I should pay a visit to this gardener. If ingredients are more potent here..."},{"a":"donovan","t":"...Then it is something I must exploit."}]},{"id":"donovan_03","i":3,"title":"Behind the Mask","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"You called for me, Miss Sia?"},{"a":"sia","t":"Ah, Lilu. Thank you for coming on such short notice."},{"a":"sia","t":"...I believe you've already acquainted yourself with Donovan?"},{"a":"lilu","t":"Oh, yes! He's a legend among alchemists! I'm so glad I got to meet him!"},{"a":"sia","t":"Approach that man with extreme caution."},{"a":"lilu","t":"H-huh!? But he's such a gentleman! Very knowledgeable, too..."},{"a":"sia","t":"Appearances can be deceiving. Behind his youthful facade lies a cunning, millennia old mastermind."},{"a":"lilu","t":"Millennia!? That's unheard of, even for elves! Do you think..."},{"a":"sia","t":"Yes. Some believe he may have discovered a sort of elixir of immortality."},{"a":"lilu","t":"Wow! I wouldn't mind adding that recipe to my grimoire!"},{"a":"sia","t":"As would many rulers. I suspect he may have the Kern emperor dancing to his tune."},{"a":"lilu","t":"...Politics sure are complicated."},{"a":"lilu","t":"But thanks! I'll be careful around him!"},{"a":"sia","t":"I knew you would understand."},{"a":"sia","t":"As for me, I'll make sure to keep him away from our... impressionable king."},{"a":"lilu","t":"Yeah... that's probably for the best."}]},{"id":"donovan_a","i":3,"title":"Ten Gold's a Steal","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"leather","t":"Hey, potion dude. You got a sec'?"},{"a":"donovan","t":"Ugh... vagabonds."},{"a":"donovan","t":"To whom do I owe this... pleasure?"},{"a":"leather","t":"I'm Tamas, the leather guy."},{"a":"leather","t":"Heard you could fix up a cool elixir of immortality, dude. Can I get a bottle?"},{"a":"donovan","t":"...I have no idea where you've caught wind of this rumor."},{"a":"donovan","t":"Even if it were true, you can be certain I would not be giving away something so valuable."},{"a":"leather","t":"I'll give you ten gold for it."},{"a":"donovan","t":"Absolutely NOT. Wars have been fought over this recipe! Emperors all over the world beg for a mere taste!"},{"a":"leather","t":"You drive a hard bargain, dude. Fifteen gold, final offer."},{"a":"donovan","t":"Has the smell of leather addled your brain, vagrant? I would not part with this recipe for all the gold in the world!"},{"a":"donovan","t":"I must be off. Please never speak to me again."},{"a":"leather","t":"Dang, I almost had it."},{"a":"leather","t":"...Guess I'll have to find another treat for those sheep."}]}]},{"id":"hemma","name":"Hemma","chapters":[{"id":"hemma_01","i":1,"title":"Looming Shadow","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"hemma","t":"...And so the Troublin fell, but not before landing some blows on my companions."},{"a":"hemma","t":"Please see to it that they are healed."},{"a":"priest","t":"But of course. I will tend to their wounds posthaste."},{"a":"lilu","t":"Hi! I heard there was a new spellcaster in town."},{"a":"lilu","t":"I'm Lilu! Pleased to make your acquaintance!"},{"a":"hemma","t":"You are correct, young Lilu. Our name is Hemma. "},{"a":"lilu","t":"...\"Our\"?"},{"a":"hemma","t":"...Yes. Necromancy takes a toll on its practitioners..."},{"a":"hemma","t":"A part of you stays across the Veil, while other things cross the threshold..."},{"a":"hemma","t":"These powers... changed us. For the best, of course."},{"a":"lilu","t":"Necromancy, you say!? Isn't that... dangerous?"},{"a":"hemma","t":"Incredibly so. But we are not satisfied with simple tricks anymore."},{"a":"hemma","t":"Now, if you'll excuse us, we need to be elsewhere. Farewell."},{"a":"lilu","t":"A necromancer... That is some pretty dark magic, Pollux! But it's the first time I can see a practitioner for real!"},{"a":"lilu","t":"She didn't seem so bad... Did she?"}]},{"id":"hemma_02","i":2,"title":"At Any Cost","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"elderowen","t":"A necromancer...?"},{"a":"elderowen","t":"I'm not sure what to make of all this..."},{"a":"hemma","t":"You are right to worry. Necromancy is a dangerous art that would consume lesser beings..."},{"a":"hemma","t":"But we are not lesser in any way."},{"a":"elderowen","t":"What about the adventurers that go with you? Do you not drain them to empower your spells?"},{"a":"hemma","t":"Only with their consent. The effects are not permanent."},{"a":"hemma","t":"And we do pay them handsomely for their services."},{"a":"elderowen","t":"I suppose you are doing some good after all..."},{"a":"elderowen","t":"Very well. I suppose you can be a sanctioned Champion of our city."},{"a":"hemma","t":"We did not need your approval... but we thank you."},{"a":"elderowen","t":"So what brought you here to our city?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"We simply seek knowledge and power. "},{"a":"hemma","t":"There is... a task we must do."},{"a":"elderowen","t":"How very vague..."},{"a":"hemma","t":"And it will stay this way. Farewell."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"There is much sadness in those eyes..."}]},{"id":"hemma_03","i":3,"title":"The Enemy Within","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"herbalist","t":"...Unripe Living Roots, and an extra chunky Spooky Ectoplasm. Anything else?"},{"a":"hemma","t":"That will be all. We shall visit the shopkeeper for the rest."},{"a":"herbalist","t":"Thank you, come again!"},{"a":"hemma","t":"<c4>...Don't forget the Grim Talons.</c4>"},{"a":"hemma","t":"Ah, yes. A pair of Grim Talons, please."},{"a":"herbalist","t":"...What was THAT just now?"},{"a":"hemma","t":"Pay it no mind. A mere passenger, if you will."},{"a":"hemma","t":"<c4>Let-me-out-let-me-out-let-me-out-let-me-out.</c4>"},{"a":"hemma","t":"Ugh. Settle down, will you?"},{"a":"hemma","t":"You may keep the change. Farewell."},{"a":"herbalist","t":"...Thanks for the tip... and the nightmares."}]},{"id":"hemma_a","i":3,"title":"Among Immortals","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"donovan","t":"Unripe Living Roots? Interesting choice."},{"a":"hemma","t":"What of it?"},{"a":"donovan","t":"Living Roots are potent reagants for many magics related to youth and lifespan."},{"a":"donovan","t":"Might you be a fellow alchemist? A quest for longevity, perhaps?"},{"a":"hemma","t":"...You would ask a lady her age? How... unbecoming."},{"a":"hemma","t":"We are no alchemist. Blood sacrifices are much more efficient."},{"a":"donovan","t":"Ah, necromancy! A respectable, but misunderstood field."},{"a":"hemma","t":"As for our age... we stopped counting quite a while ago."},{"a":"donovan","t":"I can definitely relate. Decades just seem to fly by after the first few centuries!"},{"a":"donovan","t":"It gets lonely among all these mayflies, doesn't it?"},{"a":"hemma","t":"Lonely, we are not. You would do well not to pry in a Necromancer's business."},{"a":"donovan","t":"Of course. I would not wish to intrude. Farewell!"},{"a":"donovan","t":"Strange necromancer... Have we met before?"},{"a":"donovan","t":"...Fairlyn?"}]},{"id":"hemma_04","i":4,"title":"Exorcism","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Don't worry, Hemma. I'm here! I brought Freyja!"},{"a":"priest","t":"Hemma, was it? Please relax. Let the exorcism flow through you..."},{"a":"hemma","t":"We don't recall asking for your assistance."},{"a":"hemma","t":"<c4>Beat it, kids. I ain't going anywhere.</c4>"},{"a":"lilu","t":"Aaaah! It's taking over! Quick, Freyja!"},{"a":"priest","t":"I... can't! Something's blocking my prayers..."},{"a":"hemma","t":"We are. Stop that."},{"a":"priest","t":"Are you... willingly hosting this malevolent spirit!?"},{"a":"hemma","t":"He has gone a bit mad over time, I admit."},{"a":"hemma","t":"<c4>I'm the victim here! Let me out!</c4>"},{"a":"hemma","t":"Ugh. More rude than malevolent, I can assure you."},{"a":"hemma","t":"This matter does not concern you. Please do not get involved, Freyja."},{"a":"priest","t":"Those necromancers... always toying with powers they don't understand!"},{"a":"lilu","t":"It's OK Freyja! I'm sure she knows what she's doing!"},{"a":"lilu","t":"...Right?"}]},{"id":"hemma_05","i":5,"title":"She of Two Minds","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"hemma","t":"<c4>Looks like the cat's out of the bag again. Ready to leave town?</c4>"},{"a":"hemma","t":"YOU did this. If you could keep quiet, things would be a lot easier."},{"a":"hemma","t":"Regardless, we're not leaving yet. This town shows promise."},{"a":"hemma","t":"<c4>Fine. How about letting me out for once?</c4>"},{"a":"hemma","t":"A-absolutely not. You're hard enough to keep under control as it is."},{"a":"hemma","t":"<c4>Let-me-out-let-me-out-let-me-out-let-me-out.</c4>"},{"a":"hemma","t":"I'm doing this for your sake, Claud."},{"a":"hemma","t":"...Please remember that."}]},{"id":"hemma_06","i":6,"title":"Legacy of Lies","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Fairlyn!"},{"a":"hemma","t":"Yes?"},{"a":"lilu","t":"I knew it! Hemma's just a fake name! You're the monster, Fairlyn!"},{"a":"hemma","t":"Oh my. What a devious little trickster we have here."},{"a":"hemma","t":"It's true. It seems you've done your homework."},{"a":"hemma","t":"Perhaps you've also heard of Ariel the Mad? Or Astrid the Fallen?"},{"a":"lilu","t":"...I read about them... but they vanished decades ago! They can't be..."},{"a":"hemma","t":"All us, of course. Unfortunately we face much persecution, and names must be discarded..."},{"a":"lilu","t":"You're a monster! You must be stopped!"},{"a":"hemma","t":"And how do you intend to do that? \"Hemma\" is innocent. Who would believe this wild tale of yours?"},{"a":"hemma","t":"Unless, of course, you intend to stop me by yourself..."},{"a":"lilu","t":"...Hmph!"}]},{"id":"hemma_07","i":7,"title":"Soul Splice","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"hemma","t":"Still skulking about?"},{"a":"lilu","t":"I'm keeping an eye on you. You and your suspicious monologues..."},{"a":"hemma","t":"Ah, yes. Meet Claud, our husband. He's seen better days."},{"a":"hemma","t":"<c4>I want out!</c4>"},{"a":"lilu","t":"...What happened to him?"},{"a":"hemma","t":"A terrible necromantic accident. A foolish mistake left him on the brink of death."},{"a":"hemma","t":"Given our sins on this earth, the afterlife is a terrifying prospect for us necromancers..."},{"a":"hemma","t":"Unable to save his body, we did the best we could... and saved his soul."},{"a":"lilu","t":"A Soul Splice? This spell requires years of research to prepare an appropriate vessel..."},{"a":"hemma","t":"Indeed. Given the circumstances, we improvised."},{"a":"lilu","t":"Improvised? You don't mean... you bound Claud's soul to yourself!?"},{"a":"lilu","t":"A body can't support two souls! It would cause-"},{"a":"hemma","t":"Mind-shattering pain. Insanity. Worse than you can possibly imagine."},{"a":"lilu","t":"Hemma... Why...? How...?"},{"a":"hemma","t":"It is simple, little Lilu. Failure... is not an option."}]},{"id":"hemma_08","i":8,"title":"A Century's Bounty","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Too powerful to exorcise... maybe the soul could be bound to something else...?"},{"a":"hemma","t":"You're awfully cooperative. Have you developed an interest in necromancy?"},{"a":"lilu","t":"No! I hate you and everything you've done!"},{"a":"lilu","t":"...The way I see it, if that Claud guy breaks free, it'll be big trouble for everyone here."},{"a":"lilu","t":"I'm helping you fix this mess, and nothing more!"},{"a":"hemma","t":"A noble sentiment. But how could a mere child be of any help?"},{"a":"lilu","t":"Preparing a proper vessel would require decades of research and materials..."},{"a":"hemma","t":"That will not be an issue. Behold."},{"a":"lilu","t":"...! How did you get all this...? Even Black Diamonds!"},{"a":"hemma","t":"These past decades were not wasted. Our time runs short."},{"a":"hemma","t":"What is left is a proper location to conduct the ritual. We fear such a place may not exist."},{"a":"lilu","t":"Right. The soul needs a spiritual attachment to the area, or the binding will fail."},{"a":"hemma","t":"<c4>Or you could just let good ol' Claud Favius run free! He'll make lots of friends!</c4>"},{"a":"lilu","t":"Wait... did you say Favius?"}]},{"id":"hemma_09","i":9,"title":"The Haunted Castle","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"hemma","t":"What a delightfully haunted place."},{"a":"lilu","t":"It's an awful place. No sane person should ever come here."},{"a":"lilu","t":"But most importantly, according to my research..."},{"a":"lilu","t":"...A mad king from the Favius family used to rule here, centuries ago."},{"a":"lilu","t":"Maybe Claud is a distant relative? Hopefully he didn't have anything to do with that kingdom's ruin..."},{"a":"hemma","t":"...We can feel it. We are connected to this place. This is it."},{"a":"hemma","t":"We owe you a great debt, Lilu. But now you must leave us be."},{"a":"lilu","t":"Hemma... Good luck."}]},{"id":"hemma_10","i":10,"title":"Till Death Do Us Part","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"hemma","t":"A dark, haunted and secluded place, brimming with necromantic energy..."},{"a":"hemma","t":"How long have we searched for such a place?"},{"a":"hemma","t":"Now to find a suitable vessel..."},{"a":"hemma","t":"There is no need to speak. We know exactly what you wish."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"...The armor of the mad king himself, forever bound to this place."},{"a":"hemma","t":"<c1>Soul Splice!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Ugh... We feel... or I...?"},{"a":"hemma","t":"I had forgotten this feeling of solitude..."},{"a":"hemma","t":"I've suffered an eternity to save you, dear. Because I know you would've done exactly the same."},{"a":"hemma","t":"Brave adventurers will surely come. Fight them, and through carnage, heal your tortured existence."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Farewell, beloved. But only in death shall we truly part."}]},{"id":"hemma_epilogue","i":11,"title":"Epilogue","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>FOOOLS!!! YOU DARE TREAD UPON MY LANDS?</c4>"},{"a":"sia","t":"...What a troublesome foe!"},{"a":"Castle_Boss","t":"<c4>MWAHAHAHA! PUNY MORTALS!</c4>"},{"a":"argon","t":"Lady Sia! Rudo! We must retreat!"},{"a":"rudo","t":"Never! I'm not giving him an inch!"},{"a":"yami","t":"I found an exit. Hurry!"},{"a":"rudo","t":"Bah! I'll be back, you big tin can! You hear me?"},{"a":"Castle_Boss","t":"<c4>COME BACK WHEN YOU CAN PUT UP A FIGHT!</c4>"},{"a":"Castle_Boss","t":"<c4>TELL YOUR GREATEST HEROES THAT THE TYRANT KING AWAITS!</c4>"}]}]},{"id":"lilu","name":"Lilu","chapters":[{"id":"lilu_01","i":1,"title":"Precocious Apprentice","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Well, Pollux? What do you think of this new spell? Perfect, right?"},{"a":"lilu","t":"Yeah, this time we'll ace it for sure!"},{"a":"herbalist","t":"Good morning, Lilu. Here for the weekly shipment of Living Roots?"},{"a":"lilu","t":"Yes, thank you, Maribel!"},{"a":"herbalist","t":"You sure ordered a lot this week! What's your master doing with all of these?"},{"a":"lilu","t":"To be honest, about half of it is for me. I'm doing some serious studying!"},{"a":"herbalist","t":"Oh? What kind?"},{"a":"lilu","t":"Healing spells! I've spent all of last week mending cuts and bruises at the Training Hall!"},{"a":"herbalist","t":"Right, I'm sure the Heroes are glad to have you around."},{"a":"herbalist","t":"...And Argon, too!"},{"a":"lilu","t":"...!"},{"a":"lilu","t":"I- I gotta go! Thanks!"}]},{"id":"lilu_02","i":2,"title":"Grim Tidings","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Here you go, Master Grimar. This week's Living Roots."},{"a":"wizard","t":"Thank you, Lola. Here is today's homework."},{"a":"lilu","t":"Oh! A magic tome! Is it about healing!?"},{"a":"lilu","t":"\"The Miscreant's Manual to Maledictions\"...?"},{"a":"lilu","t":"This book is way too advanced! It's even got an entire section about curses!"},{"a":"wizard","t":"...Curses?"},{"a":"wizard","t":"Hmm... curses...?"},{"a":"lilu","t":"Master?"},{"a":"wizard","t":"35 years ago, on this very day... I...!"},{"a":"lilu","t":"Master Grimar!?"},{"a":"wizard","t":"...I forgot. And who might you be?"},{"a":"lilu","t":"...I'm Lilu, your apprentice. Or Lola, sometimes..."},{"a":"lilu","t":"Oh well, nevermind. I'll be studying this book. Thanks, Grim."}]},{"id":"lilu_03","i":3,"title":"Addled Mind","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"... Add in a pinch of Silver Dust and... done!"},{"a":"lilu","t":"Look at it glow! Not bad, huh Pollux?"},{"a":"lilu","t":"If the Miscreant's Manual to Malediction is correct, this potion should-"},{"a":"wizard","t":"Lola, what is all this ruckus? I'm trying to sleep here!"},{"a":"lilu","t":"Master Grimar! Thanks to your book, I brewed a very advanced potion! It should-"},{"a":"wizard","t":"You did what!?"},{"a":"wizard","t":"Well then, give it here! Let's have a taste!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"Master Grimar?"},{"a":"wizard","t":"Lilu! I-mu-mu-must be fr-freed! Le-let me out of this doltish, half-witted mm-mind!"},{"a":"lilu","t":"M-master Grimar! Are you well?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"*Burp* A little fruity!"},{"a":"wizard","t":"Not bad, Lola. Now then, back to your chores."},{"a":"lilu","t":"...That was NOT normal."}]},{"id":"lilu_a","i":3,"title":"Hoarder of Ages","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"lilu","t":"Grimar, you didn't tell me you had a second <c1>Collection Book</c1>!"},{"a":"wizard","t":"<c1>Collection Book</c1>...? That does ring a bell..."},{"a":"lilu","t":"Wow! This one's packed with info! <c1>Damocles</c1>... <c1>Amber Citadel</c1>..."},{"a":"lilu","t":"<c1>Grimar's Grand Wand</c1>...? Did you name that one?"},{"a":"lilu","t":"There's so many pages! You must've been quite the collector!"},{"a":"sundragon","t":"He most certainly was!"},{"a":"wizard","t":"Sondra... is that you, old friend?"},{"a":"lilu","t":"Wow! Do you guys know each other?"},{"a":"sundragon","t":"Indeed. Young Grimar was absolutely enamored with his Collection Book."},{"a":"sundragon","t":"I believe it earned him a prestigious title among his human peers... \"Nerd\", was it?"},{"a":"lilu","t":"Ouch..."},{"a":"sundragon","t":"We met during his quest for rare items, and created the <c1>Fusion Cauldron</c1> together."},{"a":"sundragon","t":"He would spend day and night fusing away hundreds of items... and even more during a full moon!"},{"a":"lilu","t":"All these efforts... but his collection is still incomplete!"},{"a":"lilu","t":"I swear I'll cure your condition, Master Grimar! You must finish your life's work!"},{"a":"sundragon","t":"Time certainly is cruel to mankind. I wish you luck on your quest, little one."}]},{"id":"lilu_04","i":4,"title":"Bloodline's End","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Something isn't right with Master Grimar..."},{"a":"lilu","t":"His voice, it was as though someone was speaking from within him!"},{"a":"lilu","t":"Maybe we're dealing with a complex transmutation spell?"},{"a":"lilu","t":"Or maybe even-"},{"a":"leather","t":"Dude, Lilu! Something went wrong at the king's feast!"},{"a":"lilu","t":"Tamas? What's going on?"},{"a":"leather","t":"Something about an invader in the castle, dude. Pretty spooky!"},{"a":"lilu","t":"An invader...! Oh no, this is Argon's first day as a knight!"},{"a":"lilu","t":"Thanks Tamas, I gotta go!"},{"a":"lilu","t":"Oh no...! What's going on here!?"},{"a":"lilu","t":"Argon, where are you!?"},{"a":"king","t":"Aaargh..."},{"a":"lilu","t":"KING REINHOLD!? Are you alright!?"},{"a":"king","t":"Aahh... My precious life... fleeting..."},{"a":"lilu","t":"This is bad...!"},{"a":"lilu","t":"Focus Lilu! Remember the Sage training!"},{"a":"lilu","t":"King Reinhold! Hold still! <c1>Heal</c1>!"},{"a":"king","t":"It's no use... Please... preserve my beautiful corpse..."},{"a":"lilu","t":"No effect..."},{"a":"lilu","t":"Oh no.. could it be... Poison?"},{"a":"lilu","t":"...Just like my parents...! I won't fail this time! I can't!"},{"a":"lilu","t":"<c1>Greater Poison Purge!</c1>"},{"a":"king","t":"...Aaaah... Huh?"},{"a":"lilu","t":"King Reinhold! How do you feel?"},{"a":"lilu","t":"Wait a minute... That cup shielded you from that shuriken! You weren't harmed at all!"},{"a":"king","t":"Oh! Is that so? I suppose I may have overreacted a little bit."},{"a":"king","t":"A monarch's death is a dramatic affair, after all."},{"a":"lilu","t":"Argh! Reinhold!"}]},{"id":"lilu_05","i":5,"title":"Pick your Poison","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Ugh... That was close... sort of."},{"a":"lilu","t":"If Reinhold truly was poisoned... I don't think I could've saved him."},{"a":"lilu","t":"I'll need to refocus my efforts. To ensure no one suffers loss like I did..."},{"a":"lilu","t":"Miss Sia!"},{"a":"sia","t":"Ah, the star of the hour! A knight has been dispatched to deal with the intruder. You may rest easy."},{"a":"lilu","t":"(A knight? Good luck, Argon!)"},{"a":"sia","t":"Thank you for... saving our King, despite the circumstances."},{"a":"lilu","t":"It was nothing! But if it were to happen again, I'm not sure I could help..."},{"a":"lilu","t":"Miss Sia, do you know about poisons?"},{"a":"sia","t":"Of course. The aconitum, also known as Wolf's Bane, is a terribly efficient killer."},{"a":"sia","t":"But a personal favorite of mine is Ricin. Silent, deadly, and readily available..."},{"a":"lilu","t":"Um... What about curing them?"},{"a":"sia","t":"Oh. I can't say I've ever given it much thought."},{"a":"lilu","t":"...Forget I asked."}]},{"id":"lilu_06","i":6,"title":"Master and Student","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"I'm back, Master Grimar!"},{"a":"wizard","t":"Ah, welcome back, Lola."},{"a":"lilu","t":"Can you believe it? The King was nearly assassinated!"},{"a":"wizard","t":"Is that so..."},{"a":"lilu","t":"An assassin came out of nowhere and attacked him with a shuriken!"},{"a":"lilu","t":"And then, I rushed to his help as he was dying on the floor...!"},{"a":"wizard","t":"Erm... Who are you again?"},{"a":"lilu","t":"Oh right. Your condition... I need to get back to it!"},{"a":"lilu","t":"It might be a poison, too..."},{"a":"lilu","t":"Let's see... Grimar is super old..."},{"a":"lilu","t":"What do you think, Pollux?"},{"a":"lilu","t":"Yeah, we should ask around the city!"},{"a":"lilu","t":"Maybe some of the older residents remember what a younger Grimar acted like..."}]},{"id":"lilu_07","i":7,"title":"Ancestral Knowledge","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Master Theodore!"},{"a":"master","t":"If it isn't Lilu! How can I help you today?"},{"a":"lilu","t":"I was wondering if you could tell me about Grimar, back when he was young..."},{"a":"lilu","t":"...Since you're uh... old and stuff."},{"a":"master","t":"Ho ho ho! Of course, of course."},{"a":"master","t":"Old Grimar has always been a bit of an... eccentric."},{"a":"master","t":"But back when I was a wee lad, I remember him being much sharper. My equal at chess, even."},{"a":"master","t":"After that trip to the Chronos Ruins though... He always felt a bit off, now that I think about it."},{"a":"lilu","t":"The Chronos Ruins! That's such a dangerous place!"},{"a":"lilu","t":"...An entire civilization reduced to ruins while researching time magic... "},{"a":"lilu","t":"That place is full of magical anomalies! What would Grimar have to gain by visiting such a place?"},{"a":"lilu","t":"You're right Pollux, it's our only clue. We'll have to go investigate!"},{"a":"lilu","t":"We would need an escort though... Should we ask Argon...?"},{"a":"lilu","t":"No! What if a time vortex suddenly turned him into an old man? Or like Grimar..."},{"a":"lilu","t":"...I can think of only one other person that could help us..."},{"a":"lilu","t":"It won't be easy Pollux! But we have to try!"},{"a":"lilu","t":"Thanks Theodore! You were a big help!"},{"a":"master","t":"No problem, Lilu! See you around!"},{"a":"master","t":"..."},{"a":"master","t":"...Just how smart is that owl...?"}]},{"id":"lilu_08","i":8,"title":"Common Cause","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Mister Rudo, please! Don't walk away, I need to talk to you!"},{"a":"rudo","t":"Beat it kid, I don't wanna hear it."},{"a":"rudo","t":"You and your owl can go play elsewhere!"},{"a":"lilu","t":"I know you don't like spellcasters... but I really need your help!"},{"a":"lilu","t":"I need to go deep into the Chronos Ruins, and I can't go alone! "},{"a":"rudo","t":"Why don't you ask that kid Argon, your knight in shiny armor?"},{"a":"lilu","t":"He's... uh, busy with something else at the moment..."},{"a":"lilu","t":"I guess there is no point in asking you then..."},{"a":"rudo","t":"You got that right, kid."},{"a":"tavern","t":"That is truly a shame, hun."},{"a":"tavern","t":"I heard the Chronos Ruins Cyclops Lord has never been defeated in single combat..."},{"a":"tavern","t":"It would take an exceptional warrior to escort Lilu through these ruins!"},{"a":"rudo","t":"...Never defeated you say?"},{"a":"rudo","t":"Fine. I'll bite. How much smashing do I get to do?"},{"a":"lilu","t":"A lot, I'm sure!"},{"a":"lilu","t":"You see, I need to find the source of the time flux coming from the various crystals and isolate-"},{"a":"rudo","t":"Cut it short."},{"a":"lilu","t":"...There are monsters and magical crystals to smash."},{"a":"rudo","t":"Alright, sold. You owe me one, kid."},{"a":"lilu","t":"Great! Thank you so much, mister Rudo!"},{"a":"rudo","t":"Save it for after our trip, kid. It's no walk in the park."},{"a":"lilu","t":"I'll be there to heal your wounds if you face too many monsters!"},{"a":"rudo","t":"Hmph. Not likely."},{"a":"lilu","t":"And thank you too, Naya!"},{"a":"tavern","t":"Not a problem, hun."}]},{"id":"lilu_09","i":9,"title":"Mirror World","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"rudo","t":"I'll keep the Cyclops busy! Move on ahead!"},{"a":"rudo","t":"C'mere, fat clops! I got some oats for ya!"},{"a":"lilu","t":"Got it! Good luck!"},{"a":"lilu","t":"This is it... the Chamber of Time. And according to my research..."},{"a":"lilu","t":"This basin should be connected to a fragmented timeline!"},{"a":"lilu","t":"A parallel universe where Chronos City is still thriving..."},{"a":"lilu","t":"Look, Pollux! If you gaze into the water... you can see something!"},{"a":"lilu","t":"Looks like the people of Chronos are living like normal, somewhere out there..."},{"a":"lilu","t":"Hey... doesn't this guy look like he's waving at us?"},{"a":"lilu","t":"He looks a lot like... Grimar!?"}]},{"id":"lilu_10a","i":10,"title":"Curse of Ever Years","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Grimar!!! Drink this!"},{"a":"wizard","t":"Huh? There's something... familiar about this."},{"a":"lilu","t":"It's a special draught made with Chronos Water..."},{"a":"wizard","t":"...Stabilized and twice-treated with Threads of Fate...?"},{"a":"lilu","t":"...and bound into material form with distilled Ectoplasm."},{"a":"wizard","t":"With a pinch of Deep Coral, for taste!"},{"a":"wizard","t":"Spectacular work, Lilu. A master could not be prouder."},{"a":"lilu","t":"G-grimar... You're back to normal! It worked!"},{"a":"wizard","t":"What a peculiar experience... It's like a fog just left my mind..."},{"a":"lilu","t":"I have a rough idea of how the potion works but... there's something that doesn't make sense."},{"a":"lilu","t":"We saw you in the basin! In the fragmented timeline!"},{"a":"wizard","t":"Ho ho! Is that so? I have a theory on the matter..."},{"a":"wizard","t":"Pollux, dear. Would you mind fetching old Owen? I believe there is much to explain..."}]},{"id":"lilu_10b","i":11,"title":"Timesplit Theorem","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"elderowen","t":"Dear me, old friend! That is quite the tale!"},{"a":"lilu","t":"I'm finding it hard to believe, myself... Grimar is a survivor from Chronos City?"},{"a":"wizard","t":"When the Time Spell went astray, that entire city was tossed into another timeline."},{"a":"elderowen","t":"I remember that day like it was yesterday. An entire city, gone in a flash!"},{"a":"elderowen","t":"All we found among the ruins was a lone, wandering child..."},{"a":"lilu","t":"Grimar, right? It's hard to imagine you both as kids..."},{"a":"elderowen","t":"Ho ho! We became fast friends, didn't we?"},{"a":"wizard","t":"That we did. I studied to become a wizard and look into this strange event myself."},{"a":"wizard","t":"If what Lilu saw is correct, then I believe another Grimar exists."},{"a":"lilu","t":"The other Grimar we saw... you still exist in the other timeline!?"},{"a":"wizard","t":"So it seems. At first, there were no consequences but..."},{"a":"wizard","t":"As both Grimars grew up, our life experiences and personalities began drifting apart."},{"a":"lilu","t":"And the growing magical paradox started taxing your mind..."},{"a":"lilu","t":"I understand! Drinking a potion from the Chronos Ruins must connect you back to that other timeline!"},{"a":"wizard","t":"That's my theory. I'm sure the other Grimar appreciates it, too."},{"a":"lilu","t":"Jeez... that's a lot to take in. I think I'll need to sleep on it... You coming, Pollux?"},{"a":"elderowen","t":"As for us, old Grim, I believe we have a lot of catching up to do!"},{"a":"wizard","t":"Speak for yourself, old coot! I've never felt younger!"}]},{"id":"lilu_epilogue","i":12,"title":"Epilogue","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Hi Grimar! Here's a new recipe. It should last a bit longer!"},{"a":"wizard","t":"A remarkable improvement! Your parents would be proud."},{"a":"lilu","t":"...If only I had studied alchemy a bit earlier..."},{"a":"wizard","t":"I feel the same. If I were in full control of my functions, perhaps..."},{"a":"lilu","t":"...It's fine. I decided to focus on the future. To become better, and save others from this fate."},{"a":"lilu","t":"...I'm sure that's what my parents would've wanted."},{"a":"wizard","t":"You've grown so much... I can hardly recognize you."},{"a":"wizard","t":"Actually... who are you again?"},{"a":"lilu","t":"Oh no! The effect is already wearing off! I'd better-"},{"a":"wizard","t":"Ho ho ho! Just kidding. I have a good feeling about this one."},{"a":"wizard","t":"Now then, while my head is clear. How about learning some magic?"},{"a":"wizard","t":"The master still has a few tricks!"},{"a":"lilu","t":"Oh! How about Polymorph? I'm looking forward to this!"}]}]},{"id":"malady","name":"Malady","chapters":[{"id":"malady_01","i":1,"title":"Set in Stone","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"Quest complete! Lost kids; found and rescued!"},{"a":"argon","t":"The Chronos Ruins really isn't a safe place to play."},{"a":"argon","t":"Guess I'd better find my way out, too!"},{"a":"malady","t":"...I hope the mean Troublins leave me alone today."},{"a":"argon","t":"Hi there, miss! Are you lost, too?"},{"a":"malady","t":"Don't... don't come any closer!"},{"a":"argon","t":"Huh?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Looking into my eyes will forever turn you to stone. That is the Medusa's curse."},{"a":"malady","t":"Though... you seemed nice."},{"a":"malady","t":"...I'm sorry."}]},{"id":"malady_02","i":2,"title":"He of Marble","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"*Hnnng*... Elder... Owen..."},{"a":"elderowen","t":"Lilu! What are you doing, dragging a statue around!?"},{"a":"elderowen","t":"A statue of... Argon!?"},{"a":"lilu","t":"Huff... Huff... That statue IS Argon!"},{"a":"elderowen","t":"Oh dear. Petrified, was he?"},{"a":"lilu","t":"I think so. I found him like this in the Chronos Ruins."},{"a":"lilu","t":"Rudo helped me carry him part of the way, thankfully!"},{"a":"elderowen","t":"Quite the pickle. Are you able to cure him?"},{"a":"lilu","t":"Probably! But the ingredients are rare, it won't be easy."},{"a":"lilu","t":"I'll assemble the city folks, and the shopkeeper too! I'll leave Argon in your care!"},{"a":"elderowen","t":"Of course. I hope you don't mind spending some time as a lawn ornament, my boy."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Oh, accursed pigeons! Shoo!"}]},{"id":"malady_03","i":3,"title":"Eye for an Eye","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"...This Overgrown Vine should be old enough to work. Not too many of those left..."},{"a":"lilu","t":"Next is... Medusa blood. That won't be easy."},{"a":"malady","t":"Um..."},{"a":"lilu","t":"Eek! Monster!"},{"a":"malady","t":"...Are you a friend of that human from earlier?"},{"a":"lilu","t":"Argon? Wait, did YOU do that?"},{"a":"lilu","t":"Well, that makes things a LOT easier. I just happen to need some Medusa blood, too..."},{"a":"malady","t":"No, please! I mean no harm."},{"a":"lilu","t":"As if! You turned him to stone!"},{"a":"malady","t":"...I'm sorry. I was afraid, and our eyes met."},{"a":"malady","t":"I did not know how to react... No one has ever been kind to me before."},{"a":"lilu","t":"...Sheesh, you've had it rough."},{"a":"malady","t":"If you need blood... I will provide it."},{"a":"malady","t":"In exchange, please... take me with you. I would like to apologize to him."},{"a":"lilu","t":"...Fine. I don't like it, but if I got turned to stone, I don't think Donovan would be saving us."},{"a":"lilu","t":"I'll keep an eye on you. You, however, keep your eyes off me!"},{"a":"malady","t":"...Yes. Thank you."}]},{"id":"malady_04","i":4,"title":"To Flesh and Back","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"All done! This potion should work. Splish Splash!"},{"a":"argon","t":"...Aaaah! It feels good to stretch!"},{"a":"argon","t":"Wait, what happened?"},{"a":"lilu","t":"Malady here turned you to stone by accident and wanted to apologize."},{"a":"malady","t":"H-hello. Sorry about that. I didn't mean to..."},{"a":"argon","t":"Well, no harm done! I feel great! ...Though maybe a bit stiff."},{"a":"argon","t":"You're Malady? I'm Argon, nice to meet you!"},{"a":"argon","t":"Hey, your bandana slipped. Let me fix it for you!"},{"a":"lilu","t":"Argon! No!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Argon... I'll have to teach him about Medusas..."},{"a":"malady","t":"Oh no! I'm so sorry!"},{"a":"lilu","t":"Don't be. That one's on him."},{"a":"malady","t":"I-I'm ready for another blood draw..."},{"a":"lilu","t":"I'm not familiar with Medusa physiology, but you should wait a few days between blood draws."},{"a":"lilu","t":"Stay here in the meantime. It's not safe to wander off on your own when you're weakened."},{"a":"lilu","t":"Though considering your... powers, maybe it's best to ask Elder Owen first..."},{"a":"malady","t":"...Yes."}]},{"id":"malady_05","i":5,"title":"Welcome Home","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Elder Owen, we're back!"},{"a":"elderowen","t":"Argon was cured? Excellent news!"},{"a":"lilu","t":"Not... quite yet. But-"},{"a":"malady","t":"..."},{"a":"elderowen","t":"B-by the Goddess! A Medusa, here!?"},{"a":"lilu","t":"That's Malady. She's helped me cure Argon!"},{"a":"lilu","t":"She'll need to stay here for a few days so we can cure him... again."},{"a":"elderowen","t":"I... see. I certainly don't feel any malice from you. Forgive my reaction, Malady."},{"a":"malady","t":"Because of my curse... I am hated by all, even other monsters. I am used to this."},{"a":"elderowen","t":"The city's doors are always open to those who wish to work for the benefit of all."},{"a":"malady","t":"...Truly?"},{"a":"elderowen","t":"So long as you keep your eyes covered, I don't see any harm."},{"a":"elderowen","t":"Malady... I wish you better luck here than among your kind."},{"a":"malady","t":"Thank you... I've never been welcome anywhere before..."},{"a":"elderowen","t":"You should visit the Shopkeeper soon. There's always work available there for young folks like you."},{"a":"lilu","t":"Right! You could go on quests with us!"},{"a":"malady","t":"I will... Thank you, Lilu and Owen."}]}]},{"id":"polonia","name":"Polonia","chapters":[{"id":"polonia_01","i":1,"title":"Landlubber Extraordinaire","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Landlubbers!"},{"a":"polonia","t":"Have ye ever dreamt of daring tales of swashbucklin' and piracy on the high seas?"},{"a":"polonia","t":"I, Cap'n Polonia Del Monte, be recruiting a crew for me ship!"},{"a":"polonia","t":"As granddaughter of the legendary pirate Baross Del Monte, I can promise ye booty and adventure!"},{"a":"argon","t":"Captain Polonia, was it?"},{"a":"polonia","t":"Aye. Ye interested? A fine stud like ye would be welcome."},{"a":"argon","t":"S-stud!?"},{"a":"argon","t":"Er-hem, not really! I'm Argon, knight-in-training!"},{"a":"argon","t":"Piracy is illegal so... please surrender and come peacefully!"},{"a":"polonia","t":"Shiver me timbers! A blasted knight..."},{"a":"polonia","t":"Err, ye see, I'm a legal pirate, like that... Robin Hood landlubber."},{"a":"polonia","t":"...I steal from the rich and give to the poor!"},{"a":"argon","t":"Oh! That does sound rather noble. Fair enough, carry on!"},{"a":"polonia","t":"...Whew."},{"a":"tavern","t":"No luck today either, huh?"},{"a":"polonia","t":"Arr, life on the high seas be tough."}]},{"id":"polonia_02","i":2,"title":"The Tale of Del Monte","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"tavern","t":"No more recruiting today, Polonia?"},{"a":"polonia","t":"It be useless. I be a failure as a pirate captain, let alone bearing the Del Monte name..."},{"a":"tavern","t":"This Baross Del Monte... your grandfather, was it?"},{"a":"polonia","t":"Aye! A legend among legends! The modern times be tough for us pirates..."},{"a":"polonia","t":"All the merchant ships these days carry fancy magical detection tools to easily avoid us sea dogs."},{"a":"polonia","t":"But not Baross! Magic or not, he struck undetected from the fog!"},{"a":"polonia","t":"Robbed them blind of all their valuables, leaving only his echoing laughter as his calling card..."},{"a":"polonia","t":"Even after every other pirates had retired, he continued to terrorize the seas for decades!"},{"a":"tavern","t":"That's quite a legacy to live up to!"},{"a":"polonia","t":"Aye! And after each voyage, he would always find time to visit his granddaughter and regale her with tales of adventure..."},{"a":"polonia","t":"\"Raise the black flag! Fire the cannons! All men starside, ready to plunder!\""},{"a":"tavern","t":"Starside? Isn't it called starboard?"},{"a":"polonia","t":"...Argh! Blast it all! I'm just a landlubber with a fancy costume, trying too hard to talk like a pirate."},{"a":"polonia","t":"What's a pirate without a ship, anyway!?"},{"a":"tavern","t":"No ship, huh? Maybe you should start there."},{"a":"polonia","t":"Huh?"},{"a":"tavern","t":"A captain without a ship won't be pulling a crew anytime soon!"},{"a":"tavern","t":"But if a ship is what you need, I think I know the right man for the job."},{"a":"polonia","t":"...Really?"},{"a":"polonia","t":"I mean, by the Jolly Roger, thank ye, tavern lady! Cap'n Polonia owes ye one!"},{"a":"tavern","t":"Oh believe me, I'm counting on it."}]},{"id":"polonia_03","i":3,"title":"Downright Shipwright","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"carpenter","t":"You want me to build an entire ship!?"},{"a":"polonia","t":"Aye. Can ye do it?"},{"a":"carpenter","t":"You bet! This will be my masterpiece! Let me see those plans."},{"a":"carpenter","t":"Hmm... they are quite elaborate. What are these scribbles?"},{"a":"polonia","t":"Me handwriting. I can't read."},{"a":"carpenter","t":"Ah, well that explains a few things. Still, these are more than enough."},{"a":"polonia","t":"Yo ho ho! It'll be the greatest ship these seas have seen since Baross and Bonaventura!"},{"a":"carpenter","t":"There is the matter of funding, though. Are you sure you can afford this?"},{"a":"polonia","t":"Aye, dubloons won't be a problem. Craft the ship, I'll bring yer booty."}]},{"id":"polonia_a","i":3,"title":"Getting a Leg Up","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"polonia","t":"Ahoy, pretty lady. Yer a healer, aren't ye?"},{"a":"priest","t":"Ah, yes! I am Freyja, priestess of this tem-"},{"a":"polonia","t":"Chop me leg off."},{"a":"priest","t":"Excuse me?"},{"a":"polonia","t":"I asked ye to chop me leg off!"},{"a":"priest","t":"Goodness gracious, no! Why would anyone ever want this?"},{"a":"polonia","t":"I be a pirate! What kind of pirate cap'n doesn't have a blasted peg leg!?"},{"a":"polonia","t":"Just chop me leg off and stitch it up with yer fancy magic!"},{"a":"priest","t":"Absolutely not. I've sworn an oath to the Goddess never to harm a human being."},{"a":"polonia","t":"Argh, useless landlubbers! Fine! But ye won't be gettin' any of me dubloons!"},{"a":"priest","t":"...What a strange girl."}]},{"id":"polonia_04","i":4,"title":"Captain's Share","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"polonia","t":"Arr, these Yetis be loaded with loot! I'll be paying for me ship in no time!"},{"a":"leather","t":"Alright, dude, I'm here. So what do I do?"},{"a":"polonia","t":"That's Cap'n Polonia for ye, swabbie!"},{"a":"leather","t":"Sure thing, captain dude. What do you want me to do?"},{"a":"polonia","t":"Ye brought yer cart. Ye carry the booty while I rob these Yetis blind."},{"a":"leather","t":"Wow, captain dude, you steal from these beautiful, furred creatures?"},{"a":"polonia","t":"Aye. For some reason, they be carrying tons of valuables like Warhammers and Compound Bows."},{"a":"leather","t":"What about the pelts, captain dude? Can I have them?"},{"a":"polonia","t":"Know yer place, swabbie! Pirates plunder, they don't kill!"},{"a":"leather","t":"Oh, that's a waste."},{"a":"polonia","t":"Not at all. If ye leave yer victims alive, they gather up more loot ye can plunder later. Basic economics!"},{"a":"polonia","t":"Now keep up if ye want yer share, swabbie!"},{"a":"leather","t":"Aye aye, captain dude."}]},{"id":"polonia_05","i":5,"title":"Maiden Voyage","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"carpenter","t":"Behold, my life's work and masterpiece!"},{"a":"polonia","t":"It... it be beautiful. Ye brought a tear to this old salt's eye."},{"a":"carpenter","t":"Isn't it? I had to cut in a few places, namely your strange insistence for cannons atop the crow's nest..."},{"a":"carpenter","t":"But I think it turned out more than fine, don't you think?"},{"a":"polonia","t":"That it did, matey. Here's yer dubloon, ye earned it."},{"a":"carpenter","t":"I certainly did! One last thing though. While I may be a master carpenter, cloth and fabric are beyond me."},{"a":"carpenter","t":"...And without a sail, your ship won't be leaving port anytime soon!"},{"a":"polonia","t":"Ye've done yer Cap'n proud already, matey. I have a sail right here."},{"a":"carpenter","t":"Wow! Now that's a work of art! Magical, too! Where did you get that?"},{"a":"polonia","t":"A heirloom from me grandpappy Baross. The very sail once atop his ship - the Bonaventura!"},{"a":"carpenter","t":"I see! A remarkable finishing touch to this vessel!"},{"a":"carpenter","t":"Well then, Captain Polonia, the Splendid Allan is yours!"},{"a":"polonia","t":"Ye named her the Splendid Allan? Hold on..."},{"a":"polonia","t":"That figurehead... it's ye!? And butt naked, too!"},{"a":"carpenter","t":"Hah hah! I can think of no finer figurehead for such a perfect ship!"}]},{"id":"polonia_b","i":5,"title":"Leg It!","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"polonia","t":"Ahoy, ye there."},{"a":"wood","t":"Yeah?"},{"a":"polonia","t":"Chop me leg off."},{"a":"wood","t":"Sure."},{"a":"polonia","t":"I said- wait, yer ok with this?"},{"a":"wood","t":"Yeah, sure. Just hold your leg out like this. This old axe should do the trick."},{"a":"polonia","t":"Err, hold on!"},{"a":"wood","t":"It won't be pretty, but you're a tough girl, aren't you?"},{"a":"wood","t":"Just make sure to apply a good tourniquet. Wouldn't want you bleeding out, now."},{"a":"polonia","t":"Avast, matey! Slow down!"},{"a":"polonia","t":"I- me ship's sailing soon! I-I gotta go catch it! See ya, matey!"},{"a":"wood","t":"...Hah! Humans. Never a dull moment."}]},{"id":"polonia_06","i":6,"title":"Legacy at Sea","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"My King, I bring dire news."},{"a":"king","t":"Oh no! Has the Lost City of Gold run out of gold!?"},{"a":"sia","t":"Nothing so dire, mercifully."},{"a":"sia","t":"However, I fear a meddlesome pirate has been plundering your personal merchant fleet."},{"a":"sia","t":"...The theft is estimated to be upwards of 100 trillion gold."},{"a":"king","t":"By the Goddess! What of my fleet's state-of-the-art magical pirate detection?"},{"a":"sia","t":"Utterly inefficient, it seems. Much like the great Baross himself, this ship eludes even our best magic..."},{"a":"sia","t":"...Plundering your gold before slipping away into the sea."},{"a":"king","t":"Absolutely barbaric! What of the crew?"},{"a":"sia","t":"Spared, my King. So long as they offer no resistance."},{"a":"king","t":"Gold is a small price to pay then. I shall eat peasant meals until my fortune is restored!"},{"a":"king","t":"...How long will it take?"},{"a":"sia","t":"Approximately 2 days, my King."},{"a":"king","t":"Dark times indeed...."}]},{"id":"polonia_07","i":7,"title":"Shore Leave","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Captain Polonia be ashore! Rounds be on me!"},{"a":"tavern","t":"Polonia! Or should I say... Captain Polonia! I take it your \"business\" is going well?"},{"a":"polonia","t":"Ye bet yer landlubber bottoms it be! These seas be ripe for plunderin'!"},{"a":"polonia","t":"Wherever me ship goes, me grandpappy's sails catch the wind like nothing I ever seen!"},{"a":"tavern","t":"I'm sure Baross would be proud. How do you intend to spend these... ill-gotten goods?"},{"a":"polonia","t":"Like any good pirate. Buried it here and there with me crew."},{"a":"tavern","t":"Oooh! Treasure maps! How exciting!"},{"a":"polonia","t":"Aye, that's how pirates be. Keep some for ye cold winter months, like them squirrel landlubbers."},{"a":"tavern","t":"And what about the rest?"},{"a":"polonia","t":"Gave it to the pretty temple lady."},{"a":"tavern","t":"An orphanage donation? I did not take you for the charitable type."},{"a":"polonia","t":"Orpha what?"},{"a":"tavern","t":"Ah, never mind. So what can I get you, Captain?"},{"a":"polonia","t":"Me favorite; Old Salt's Brew! And to any landlubber who think they can hold it down..."},{"a":"polonia","t":"Next round's on me! The Baross family is back at sea! Yo ho ho!"}]},{"id":"polonia_08","i":8,"title":"Whispers from the Past","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"polonia","t":"Ready for yer next dive, merman?"},{"a":"baker","t":"Anytime, captain! Though I must say..."},{"a":"baker","t":"While I'm always happy to help with underwater exploration, I didn't sign up for piracy!"},{"a":"polonia","t":"Worry not yer brains, matey. We be on a charting mission. Yer captain's expanding her territory."},{"a":"polonia","t":"No piracy today. But if we're lucky, we might find a sunken ship to plunder! Yo ho ho!"},{"a":"baker","t":"Um, captain? What's this ship on the horizon?"},{"a":"polonia","t":"Arr. Calm yer fishtail, merman. This be the Bonaventura! Me grandpa's ship."},{"a":"baker","t":"Are you sure? It looks rather worn down..."},{"a":"polonia","t":"...By Neptune's beard! T-the blasted Bonaventura! B-but that's impossible! Me grandpa's long dead!"},{"a":"polonia","t":"M-mateys! Change o' plans! WE ARE TAILING THIS SHIP!"}]},{"id":"polonia_09","i":9,"title":"A Legend Adrift","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"baker","t":"...Never thought I'd be boarding a derelict ship in my life."},{"a":"polonia","t":"Watch yer footing, merman. This ship's in poor shape."},{"a":"baker","t":"To be honest, I'd much rather take a swim! What are we doing on this vessel in the first place?"},{"a":"polonia","t":"What'dya mean what we're doing? This be Baross' Bonaventura!"},{"a":"polonia","t":"I gots to figure out what happened here... This derelict ship shouldn't be sailing..."},{"a":"baker","t":"...Ghost ship, more like."},{"a":"polonia","t":"Argh, don't ye scare me like that! Ghosts don't exist!"},{"a":"baker","t":"What about Zo-"},{"a":"polonia","t":"S-shut yer breathing hole, matey. I be looking for clues."},{"a":"baker","t":"This journal over there is looking a bit eerie..."},{"a":"polonia","t":"Arr, the captain's logs!"},{"a":"baker","t":"Feels like it's looking at you... isn't it?"},{"a":"polonia","t":"Yer comin' with me, journal. Keep yer pirate eyes peeled for anythin' else."},{"a":"polonia","t":"...Matey, can ye stop touchin' me hair?"},{"a":"baker","t":"Captain, I'm over here."},{"a":"polonia","t":".....AAAAAARGH!!! Abandon ship!"}]},{"id":"polonia_10","i":10,"title":"Pirate Inheritance","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"polonia","t":"Yer Captain's back on board, crew. Hoist the sails, we be leavin'."},{"a":"baker","t":"Captain, look! The Bonaventura is sinking!"},{"a":"polonia","t":"Barnacles! How is this possible? After all this time!? Was the journal keepin' it floatin'?"},{"a":"baker","t":"...Perhaps it fulfilled its purpose."},{"a":"polonia","t":"Baross, ye sea dog... how could ye know...?"},{"a":"baker","t":"Polonia, what about the log?"},{"a":"polonia","t":"Ye be right, lemme see..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"...I have another favor to ask ye, merman."},{"a":"baker","t":"Ah yes, let me read that for you."},{"a":"baker","t":"Hmm... seems like instructions to find some underwater place."},{"a":"polonia","t":"Sunken Temple? That be old news."},{"a":"baker","t":"No, it seems rather far away from there... Something about the Lost City of Gold?"},{"a":"baker","t":"The Lost City of Gold isn't underwater though..."},{"a":"polonia","t":"Y-ye mean it wasn't a story? That place be real?"},{"a":"polonia","t":"Merman, ye can swim. This be fate."},{"a":"polonia","t":"If the stories be true... ye won't regret takin' me there."}]},{"id":"polonia_11","i":11,"title":"The Sunken City of Gold","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"baker","t":"Whew! We're here! How are you holding up, Captain?"},{"a":"polonia","t":"*Cough* *Ack*..."},{"a":"polonia","t":"Wheeze... ye got... some strong legs on ya... for a merman..."},{"a":"baker","t":"And I'm glad I do! This entrance is so deep underwater, I don't think any human could make it here."},{"a":"polonia","t":"Yer right! I almost drowned. Ne'er comin' back here again..."},{"a":"baker","t":"By the Goddess... Polonia, look around!"},{"a":"polonia","t":"Barnacle beard... The Sunken City of Gold..."},{"a":"polonia","t":"This place... I've never seen anything like this..."},{"a":"baker","t":"It's overflowing with riches! Gold, pearls... The Lost City of Gold looks drab in comparison!"},{"a":"polonia","t":"All his life, me grandpa searched for this place..."},{"a":"baker","t":"In the end, he couldn't carry anything back to land, so he left it all to his favorite granddaughter."},{"a":"polonia","t":"Sniff... I'm getting all teary-like..."},{"a":"baker","t":"Would you like a moment, Captain?"},{"a":"polonia","t":"Ye kiddin'? There's loot to be plunderin'! And ye just got promoted to First Mate. Ye ready for a few swims?"},{"a":"baker","t":"I gotta carry bags of loot AND a pirate? I'd better stretch!"}]},{"id":"polonia_epilogue","i":12,"title":"Epilogue","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"polonia","t":"Hmm..."},{"a":"baker","t":"Are we preparing for another swim, Polonia?"},{"a":"polonia","t":"Nay, matey. I got a big problem."},{"a":"polonia","t":"I got too much money! Almost running out o' beaches to bury it all."},{"a":"baker","t":"I must say, I'm a bit overwhelmed with my share, myself!"},{"a":"baker","t":"Oh, that reminds me!"},{"a":"baker","t":"I went for a swim around the sunken Bonaventura earlier..."},{"a":"baker","t":"There wasn't much of note, but I did find this eyepatch. Anything you recognize?"},{"a":"polonia","t":"First Mate! That be Baross' eyepatch!"},{"a":"polonia","t":"Yo ho ho! I'm so happy, I could kiss ye!"},{"a":"baker","t":"Pleasure is all mine, Captain. I'm sure that's what he would've wanted."},{"a":"polonia","t":"...Ye know what, I'm done with this underwater lootin' business."},{"a":"polonia","t":"The sea be the pirate's home, not some city of gold! No matter how full o' booty it be."},{"a":"polonia","t":"As the granddaughter of the great Baross, I gift ye the Sunken City of Gold and all its remaining booty."},{"a":"polonia","t":"Thank ye for yer service, First Mate. If ye ever change yer mind about piracy, yer more than welcome to join us."},{"a":"baker","t":"Thank you, Captain. I'll never forget our adventures together!"},{"a":"baker","t":"...Guess I'd better have another talk with Tutu Mano about that vacation back home!"}]}]},{"id":"king","name":"Reinhold","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"King Reinhold..."},{"a":"king","t":"Ah... It would seem my duties have caught up to me!"},{"a":"sia","t":"\"Piled up\", I would rather say. Dignitaries are waiting."},{"a":"king","t":"Farewell, shopkeeper! I shall return!"},{"a":"sia","t":"I don't think so, no."}]},{"id":"king_01","i":1,"title":"The King's Court","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"king","t":"The king's court is now open! Petitioners, step forth!"},{"a":"rudo","t":"Hmph."},{"a":"king","t":"What can Reinhold's kingdom do for its subjects, large... bear-man?"},{"a":"rudo","t":"I think you should ban all magic and kick out the spellcasters."},{"a":"king","t":"Ah... that is... erm..."},{"a":"king","t":"We shall... take your proposition into consideration! Next!"},{"a":"herbs","t":"Hiii! I think we should make every day into PIÑATA DAY!"},{"a":"king","t":"What a splendid idea! In fact, we could-"},{"a":"sia","t":"..."},{"a":"king","t":"...spend much time debating the matter! Thank you for coming!"},{"a":"king","t":"...Sia, how many more petitioners today?"},{"a":"sia","t":"Fifty five, my King."},{"a":"king","t":"Oh dear."}]},{"id":"king_02","i":2,"title":"Foolish Heart of Gold","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"donovan","t":"Pardon me, is this seat taken?"},{"a":"sia","t":"Come to poison my day off, Donovan?"},{"a":"donovan","t":"You wound me, Sia. I am merely getting in touch with a fellow Imperial citizen."},{"a":"donovan","t":"How is our foolish King doing these days?"},{"a":"sia","t":"Your spying must be getting rusty, Dononvan. Reinhold is far from the fool you believe him to be."},{"a":"sia","t":"Though he smiles, he sacrifices much for his people."},{"a":"sia","t":"Something the Emperor... OUR Emperor, could learn from."},{"a":"sia","t":"My role so far has been to keep him from ruining himself in the name of his people."},{"a":"donovan","t":"Is that so? Fascinating."},{"a":"sia","t":"He is a fool with a heart of gold, yes. But underestimate him at your own peril."}]},{"id":"king_03","i":3,"title":"Royal Afterhours","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"king","t":"Whew! This pile of reports isn't getting any smaller, is it?"},{"a":"sia","t":"It appears we should brace for another all-nighter."},{"a":"king","t":"Thank you for assisting me through this, dear Sia!"},{"a":"sia","t":"It is nothing, my King. Now then, onto the next report..."},{"a":"sia","t":"The farmers from Southburg have come short on their taxes, citing a poor harvest."},{"a":"sia","t":"I believe this is the second time, now..."},{"a":"king","t":"Send some of my court wizards to investigate. Perhaps some blight curses their lands."},{"a":"sia","t":"A most generous solution."},{"a":"king","t":"And forgive their taxes again. It's what my father would've wanted!"},{"a":"sia","t":"Very well. I do believe King Keinan would've done the same."},{"a":"king","t":"The crown he's left behind is heavy indeed..."},{"a":"king","t":"What does the next report say?"},{"a":"sia","t":"This report speaks of border tensions with the neighboring Empire..."}]},{"id":"king_04","i":4,"title":"Jumping at Shadows","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"My King-"},{"a":"king","t":"Eek!"},{"a":"king","t":"P-please announce your presence if you are to sneak up behind me!"},{"a":"sia","t":"Ah, that ninja's attack weighs heavily upon your mind, does it not?"},{"a":"king","t":"Of course! I lived but by a hair's breath!"},{"a":"sia","t":"Shall I double the guard?"},{"a":"king","t":"That... will not be necessary. But please do not step so lightly in the future!"},{"a":"sia","t":"As you wish, my King."},{"a":"hemma","t":"Ah, it is good to be home... Huh?"},{"a":"king","t":"ARGH!!! N-ninjas!?"},{"a":"hemma","t":"Our apologies. It seems we were off the mark."},{"a":"hemma","t":"Shadow Translocation can be somewhat inaccurate, at times."},{"a":"king","t":"P-please refrain from performing SHADOW TELEPORTATION within my throne room!"},{"a":"sia","t":"K-king Reinhold? Are you well?"},{"a":"king","t":"Yes! Please show this... ghastly visitor to the exit."},{"a":"sia","t":"Very well. I shall ensure the castle is properly warded against such intrusions in the future."},{"a":"hemma","t":"This is quite the amusing Waypoint we've found. We shall return."},{"a":"king","t":"I would rather hope not!"}]}]},{"id":"rudo","name":"Rudo","chapters":[{"id":"rudo_01","i":1,"title":"The Living Mountain","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"Brrr... I'm not dressed for this cold! Why are we here again?"},{"a":"lilu","t":"The gems here have some wonderful properties! Grimar told me-"},{"a":"argon","t":"Wait, Lilu! Look! There's a man fighting a Yeti over there!"},{"a":"lilu","t":"A man!? He's as big as a mountain!"},{"a":"lilu","t":"And he's... suplexing the Yeti!?"},{"a":"rudo","t":"Whew... That's ten."},{"a":"argon","t":"Impressive battle, sir! You were awesome!"},{"a":"rudo","t":"Huh?"},{"a":"lilu","t":"Mister... you're wounded! Let me heal you!"},{"a":"lilu","t":"<c1>Hea-</c1>...!"},{"a":"rudo","t":"BACK OFF!"},{"a":"rudo","t":"I'm fine. It'll heal on its own."},{"a":"rudo","t":"Kids shouldn't be hanging out in a place like this. Go home."},{"a":"argon","t":"Wow, that guy really hates magic, huh?"},{"a":"lilu","t":"No. What I saw in his eyes... It was fear."}]},{"id":"rudo_02","i":2,"title":"Eviction Notice","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"elderowen","t":"I'm afraid I don't follow..."},{"a":"rudo","t":"Bah! Then I'll make it simple for your codger ears to understand!"},{"a":"rudo","t":"The wizard in this city is a raving lunatic and should be kicked out, for everyone's safety."},{"a":"elderowen","t":"My my... such harsh words..."},{"a":"rudo","t":"Just yesterday, he told me to keep an eye on Timotheus..."},{"a":"rudo","t":"...Claiming that \"Tim\" was delusional, confused, and should be kept under supervision."},{"a":"rudo","t":"He *IS* Timotheus!"},{"a":"elderowen","t":"Hmm, yes. I see."},{"a":"elderowen","t":"Despite his... \"condition\", Timotheus Grimar is an integral part of this city."},{"a":"elderowen","t":"He is as helpful as he is harmless. I see no cause for alarm."},{"a":"lilu","t":"What's this about kicking out Master Grimar!?"},{"a":"rudo","t":"Stay out of this, girl."},{"a":"lilu","t":"No! Master Grimar is a powerful wizard, but he would never hurt anyone!"},{"a":"rudo","t":"Gah! Fine! But if this town blows up, don't say I didn't warn you."},{"a":"elderowen","t":"Quite the troublemaker, that one."},{"a":"lilu","t":"I'd better keep an eye on him..."}]},{"id":"rudo_03","i":3,"title":"Spark-Born","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"priest","t":"Excuse me... What are you grumbling about?"},{"a":"rudo","t":"Blast it. Why are there so many blasted spellcasters in this city..."},{"a":"priest","t":"Ah, Mr. Rudo, I presume."},{"a":"rudo","t":"Don't get all friendly with me, wizard."},{"a":"priest","t":"I am a priestess of the Goddess, my powers differ from that of a wizard."},{"a":"priest","t":"As part of my oath, I have sworn to a life of healing and protection."},{"a":"rudo","t":"I'm not buying it. You Spark-Borns are all the same."},{"a":"priest","t":"You know about the Spark...?"},{"a":"rudo","t":"Hmph. Forget I said anything. I'm out of here."},{"a":"priest","t":"...Were you listening, Lilu?"},{"a":"lilu","t":"Yep, all of it!"},{"a":"priest","t":"Do you remember my lessons about the Spark?"},{"a":"lilu","t":"Of course! Only people born with the Spark can control and weave magic spells."},{"a":"lilu","t":"This phenomenon is generally unknown to the general public, though."},{"a":"priest","t":"That's correct! As expected of my brightest student!"},{"a":"priest","t":"Though this begs the question... How does he know about it...?"},{"a":"lilu","t":"Hmm... Do you think...?"}]},{"id":"rudo_04","i":4,"title":"Smash & Grab","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Captain Polonia really hit it big this time!"},{"a":"polonia","t":"An entire royal tomb, ready for ye ol' plunderin'!"},{"a":"rudo","t":"Keep it down, sailor girl. I'm busy."},{"a":"polonia","t":"Or it would be... if there weren't a barnacled berserker SMASHIN' ALL THE BOOTY TO PIECES!"},{"a":"polonia","t":"What in Davy Jones' name is yer problem, matey? That stuff's worth tons o' doubloons!"},{"a":"rudo","t":"It's ancient. "},{"a":"rudo","t":"It's magical."},{"a":"rudo","t":"And it's probably cursed."},{"a":"rudo","t":"I'm smashing it all to dust to save someone else the trouble."},{"a":"rudo","t":"If this city is too foolish to see the problem, then I'll take care of it myself!"},{"a":"polonia","t":"Oy, matey. That staff be looking REAL valuable. Yer not gonna..."},{"a":"rudo","t":"Hmph."},{"a":"rudo","t":"...Ouch."},{"a":"polonia","t":"By the Kraken! Don't just snap it over yer knee!"},{"a":"polonia","t":"...Though it be lookin' like the staff did the breakin'. Not even a scratch on it!"},{"a":"polonia","t":"How's yer leg, matey?"},{"a":"rudo","t":"Fine. But this staff's tougher than it looks."},{"a":"rudo","t":"And for some reason, I can't drop it. Like it's... glued to my hand."},{"a":"polonia","t":"I be no ship surgeon, but seems like ye got yerself proper cursed, matey."},{"a":"polonia","t":"...Ye might wanna get that checked out."},{"a":"rudo","t":"Of course it's cursed magic. It's ALWAYS cursed magic."},{"a":"rudo","t":"Fine. I'm out of here. Break the rest for me."},{"a":"polonia","t":"Aye aye, matey!"},{"a":"polonia","t":"...More like break n' enter, cause this pirate be plunderin' tonight! Yo ho ho!"}]},{"id":"rudo_a","i":4,"title":"Tough Love","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"herbs","t":"Gorza!"},{"a":"gems","t":"Gorza!<sprite tint=1 name=Note2>"},{"a":"wood","t":"Hey Juniper. And Maylee! What's up?"},{"a":"herbs","t":"Me and Maylee were talking about her future prince charming..."},{"a":"gems","t":"Oooh I can't wait!"},{"a":"herbs","t":"...And we were wondering... how did YOU meet yours?"},{"a":"wood","t":"That big, dumb oaf Rudo? Hah!"},{"a":"wood","t":"He may not look like it, but that man really knows how to talk to a lady."},{"a":"wood","t":"Let's see... it went a bit like this..."},{"a":"rudo","t":"...Another one, for the road."},{"a":"tavern","t":"So... Rudo. Have you ever considered settling down?"},{"a":"rudo","t":"Mind your business, Naya. I ain't got time for that."},{"a":"tavern","t":"Love strikes when you least expect it! Who knows, the woman of your dreams could walk in at any time..."},{"a":"rudo","t":"Bah! I won't settle for a woman who can't wrestle me to the ground."},{"a":"wood","t":"Is that a challenge, big guy?"},{"a":"rudo","t":"Try me, tooth face!"},{"a":"tavern","t":"Gorza, please put the chair down-"},{"a":"wood","t":"How about this, meathead? You want some more?"},{"a":"rudo","t":"RAAAAGH!!!"},{"a":"wood","t":"Woah!"},{"a":"wood","t":"...And we got married the week after. Bloodiest wedding I've ever seen."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"...M-maybe we should go ask someone else."}]},{"id":"rudo_05","i":5,"title":"Curses & Outbursts","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"rudo","t":"What do you mean, y'can't break it!?"},{"a":"master","t":"I meant just that my violent friend; I can't break this relic."},{"a":"rudo","t":"What use is an adamantine hammer if it can't break this puny staff!"},{"a":"master","t":"Well it certainly isn't that puny... It looks pretty evil to me!"},{"a":"master","t":"In any case, there is something more at work here, probably magic..."},{"a":"rudo","t":"OF COURSE it's magic."},{"a":"rudo","t":"It's always cursed magic."},{"a":"master","t":"Seems to me like you already knew this! Why not go to someone learned in such things instead of me?"},{"a":"rudo","t":"You can't trust mages... Not one bit."},{"a":"master","t":"Well I don't think you have a choice here, son."},{"a":"master","t":"Besides, how could you not trust sweet Lilu to begin with? She's adorable!"},{"a":"rudo","t":"She a mage ain't she? Means she's just like the rest."},{"a":"rudo","t":"Dangerous. Wicked. VILE."},{"a":"master","t":"Well, she's probably the only one who can help, if you want to get rid of this staff at some point."},{"a":"rudo","t":"...Blast it."}]},{"id":"rudo_06","i":6,"title":"Wizard Unwitting","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"rudo","t":"Hey Naya, the usual."},{"a":"tavern","t":"Sorry Rudo, no weapons inside. You know the rules."},{"a":"rudo","t":"This? It's a walking stick."},{"a":"tavern","t":"I don't think so! I know a magic staff when I see one!"},{"a":"rudo","t":"Pah. Fine. See this? Cursed as can be. Can't take it off."},{"a":"tavern","t":"Oh my! I suppose we can make a small exception, in that case. Just for you!"},{"a":"rudo","t":"Hmph. Thanks."},{"a":"tavern","t":"So, what are you going to do about it?"},{"a":"rudo","t":"Don't mind it. I'll just live with it."},{"a":"tavern","t":"Really? I'd dare say it's making you cranky. Crankier than usual, if that's even possible."},{"a":"tavern","t":"Plus, looking at you, anyone would think you're a mage of some kind."},{"a":"rudo","t":"...Really? A damned mage?"},{"a":"tavern","t":"All you're missing is a silly hat! And a better attitude!"},{"a":"rudo","t":"...You might be right. I gotta do something about it. See ya."},{"a":"tavern","t":"Have a nice day, now. I'll put this on your tab!"}]},{"id":"rudo_07","i":7,"title":"Glimpse of Trauma","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"rudo","t":"Sorry about earlier. I was told you could... help with this curse."},{"a":"lilu","t":"That staff, huh? Looks pretty nasty!"},{"a":"lilu","t":"I've never tried to neutralize a curse before, but in theory... I should be able to."},{"a":"lilu","t":"Are you sure you're ready for this? You're really tense."},{"a":"rudo","t":"...Yes."},{"a":"lilu","t":"Ok! Let me focus first..."},{"a":"lilu","t":"I see the curse... wrapped all over you."},{"a":"lilu","t":"Hold on, I'll need to go deeper..."},{"a":"rudo","t":"...Nghn!"},{"a":"lilu","t":"Woah!"},{"a":"lilu","t":"It really, REALLY looked like you were about to punch me just now!"},{"a":"rudo","t":"...Sorry. Didn't mean to."},{"a":"lilu","t":"I don't think this is gonna work. I need to concentrate, y'know?"},{"a":"rudo","t":"Yeah, it's my bad. I'll find something else."},{"a":"lilu","t":"Why not ask Malady? Maybe she can see something I can't."},{"a":"rudo","t":"Malady, huh? I'll try."},{"a":"lilu","t":"Be nice, though! She has... special circumstances you should know about..."}]},{"id":"rudo_08","i":8,"title":"Curse Enough for Two","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"rudo","t":"Mrs. Malady, y'got a sec?"},{"a":"malady","t":"(Oh no, Lilu warned me about him...)"},{"a":"malady","t":"Um... sorry. I don't think..."},{"a":"rudo","t":"Sorry, didn't mean to scare ya. Thought y'might know about this staff thing."},{"a":"malady","t":"I... thought you hated magic?"},{"a":"rudo","t":"More than anything in the world."},{"a":"rudo","t":"But you're cursed aint'cha? Same as me."},{"a":"rudo","t":"You didn't choose magic. It ain't your fault."},{"a":"malady","t":"...In that case, I can try to... speak with the staff."},{"a":"malady","t":"..."},{"a":"malady","t":"...It seems to be parasitic. It is feeding on your Spark."},{"a":"rudo","t":"That thing's intelligent?"},{"a":"malady","t":"Yes... in a way."},{"a":"malady","t":"Your Spark looks extremely strong. It may take decades but..."},{"a":"malady","t":"...Maybe it can free you of your magic...?"},{"a":"rudo","t":"Hmph. Wouldn't count on it."},{"a":"rudo","t":"So all it wants is a sucker to mooch magic from, right?"},{"a":"malady","t":"Um... yes. More or less."},{"a":"malady","t":"Please... I am already cursed, so..."},{"a":"rudo","t":"Hah! Wouldn't even think about it, miss."},{"a":"rudo","t":"Thanks for the help. I think I have an idea..."}]},{"id":"rudo_09","i":9,"title":"A Soldier's Past","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"malady","t":"Um... may I come in?"},{"a":"veteran","t":"Ah, the Medusa I've heard so much about."},{"a":"veteran","t":"Come on in, rookie. Don't have any chairs your size, I'm afraid."},{"a":"malady","t":"That's fine... thank you. I wanted to ask about that man, Rudo."},{"a":"veteran","t":"That big oaf? He didn't bully you, did he?"},{"a":"malady","t":"No, he was... unusually kind with me."},{"a":"veteran","t":"Really? That's odd, he really hates magic."},{"a":"malady","t":"This is why I came. I wanted to ask... why?"},{"a":"veteran","t":"We used to be part of the Empire's army a while back. Old war buddies."},{"a":"veteran","t":"Rudo was... \"volunteered\" to be part of an experiment. One that sought to artificially implant the Spark into soldiers."},{"a":"veteran","t":"Nasty business that was. He was never the same after that."},{"a":"malady","t":"That's horrible... "},{"a":"veteran","t":"A lot worse than it sounds, too. We got out of there as soon as we could."},{"a":"malady","t":"Did it at least... work? I sensed an extremely powerful Spark inside him..."},{"a":"veteran","t":"Hard to say. You saw how he's like. Not even the Emperor himself could get him to cast the simplest spell."},{"a":"malady","t":"And now... because of this, he is afflicted with a terrible curse... How can we help?"},{"a":"veteran","t":"He came to you, didn't he? Him asking for help is a good sign! "},{"a":"veteran","t":"He ain't the smartest, but the lad's tenacious. I'm sure he'll come up with something."}]},{"id":"rudo_10","i":10,"title":"Transfer of Ownership","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"rudo","t":"Alright, you nasty chopstick. I'll cut you a deal."},{"a":"rudo","t":"I'll hand you over to that Troublin over there."},{"a":"monster_Forest_Blacksmith","t":"E-eek! Let me... go!"},{"a":"rudo","t":"You become best buds with it and we forget all this happened."},{"a":"rudo","t":"If you don't wanna do that..."},{"a":"rudo","t":"I take a dive in this lava and we see which of us lasts longer."},{"a":"rudo","t":"So what's it gonna be? The \"water\" is looking fine, if you ask me!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"...Good choice. Have fun with that, Troublin."},{"a":"monster_Forest_Blacksmith","t":"Urgh! It's... stuck!"},{"a":"rudo","t":"Gwah hah hah! So long!"}]},{"id":"rudo_epilogue","i":11,"title":"Epilogue","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"lilu","t":"Rudo! About last time..."},{"a":"rudo","t":"Hm?"},{"a":"lilu","t":"Oh! You got rid of the staff!"},{"a":"rudo","t":"That's right. One less burden to worry about."},{"a":"rudo","t":"...Sorry about last time. Was a bit on edge."},{"a":"lilu","t":"...I guess I can forgive you. But you'll need to work on your attitude towards mages!"},{"a":"rudo","t":"Hah! That Malady was unexpectedly helpful. Who knows, maybe I'll come around eventually."},{"a":"lilu","t":"Did she manage to lift the curse?"},{"a":"rudo","t":"Not exactly. But thanks to her, I found an unexpected... helping hand out there."},{"a":"rudo","t":"A little cooperation every now and then doesn't hurt. Gwah hah!"},{"a":"argon","t":"Ashley, watch out! Something else is coming!"},{"a":"ashley","t":"I'm ready for anything! C'mon, beast!"},{"a":"monster_Forest_Blacksmith","t":"...Help..."},{"a":"argon","t":"Huh?"},{"a":"ashley","t":"Huuuuh?"}]}]},{"id":"sia","name":"Sia","chapters":[{"id":"sia_01","i":1,"title":"Kingly First Steps","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"king","t":"Sia! I've decided!"},{"a":"sia","t":"Yes, my King?"},{"a":"king","t":"Today, I would like to go shopping!"},{"a":"sia","t":"An excellent idea, your Majesty."},{"a":"sia","t":"However, looking at your schedule, it seems you are to meet foreign dignitaries today..."},{"a":"king","t":"Oh, what a bore! Can't we just send them away?"},{"a":"sia","t":"Remember, my King, though you may be young, you are still King. Your word is law."},{"a":"king","t":"...You're absolutely right! Shopping it is, then! Those dignitaries can wait!"},{"a":"sia","t":"Your decisiveness is admirable. Shall I accompany you?"},{"a":"king","t":"Of course! I trust no one else with the protection of my graceful self."}]},{"id":"sia_02","i":2,"title":"Friends in Low Places","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"...And so, I have reasons to believe our King's life may be in danger."},{"a":"elderowen","t":"I see. Indeed, a few rival kingdoms would benefit from an attempt on the King's life."},{"a":"elderowen","t":"I haven't seen any suspicious characters, but I'm sure Naya over at the tavern would know more."},{"a":"sia","t":"Thank you, Elder. Your wisdom and patriotism is appreciated."},{"a":"elderowen","t":"Don't mention it. It is my duty as a resident to ensure our kingdom's prosperity."},{"a":"elderowen","t":"Though he may be young and foolish, I'm sure Reinhold will grow into a fine king... given time."},{"a":"sia","t":"And it is my duty to see him live until then!"},{"a":"tavern","t":"Well well, it's not often we see pretty blue blood down here at the tavern!"},{"a":"sia","t":"Cut the act, Naya, you know who I am."},{"a":"tavern","t":"Indeed! Sia Leonel, a gift to our King by the Kern emperor..."},{"a":"tavern","t":"To act as an advisor, but also to keep tabs on him, am I right?"},{"a":"sia","t":"...!"},{"a":"sia","t":"...Nosy girl, aren't you?"},{"a":"sia","t":"Well then, tell me, nosy Naya..."},{"a":"sia","t":"Have you seen any strange faces in your tavern lately?"},{"a":"tavern","t":"Oh, we get plenty of strange faces! Tipsy orcs, shopkeepers..."},{"a":"tavern","t":"But the strangest of all would be that girl in the corner, over there."},{"a":"yami","t":"...!"},{"a":"sia","t":"She escaped..."},{"a":"sia","t":"That was an Azuman spy! ...or assassin."},{"a":"sia","t":"I'll need to be extra vigilant..."}]},{"id":"sia_03","i":3,"title":"Gatecrasher","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"We have gathered you here today to celebrate the King's incredible generosity."},{"a":"sia","t":"In the past months, he has donated several million gold from his own coffers..."},{"a":"sia","t":"...To several local temples, schools and orphanages."},{"a":"sia","t":"All are welcome to this feast, so please tell your friends and family."},{"a":"sia","t":"Long live King Reinhold!"},{"a":"yami","t":"Tyrant Reinhold, your reign ends now!"},{"a":"king","t":"Aaargh..."},{"a":"sia","t":"A shuriken...! The Azuman spy!"},{"a":"sia","t":"Guards! Form a perimeter around the castle! Let none escape!"},{"a":"sia","t":"Argon, go after that assassin!"},{"a":"argon","t":"At once!"},{"a":"sia","t":"You! Unwashed buffoon! The King is injured! Seek out a healer at once!"},{"a":"leather","t":"Wow, rude, dude."},{"a":"sia","t":"(I had every entry point under maximum surveillance...)"},{"a":"sia","t":"(...Just who is this girl?)"}]},{"id":"sia_04","i":4,"title":"Mail Scorched Black","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"Nosy Naya, I believe you owe me some explanations."},{"a":"tavern","t":"Oh, Mrs. Leonel... I believe YOU owe me explanations."},{"a":"sia","t":"I beg your pardon?"},{"a":"tavern","t":"I've intercepted some VERY interesting letters. Sent by you, I believe."},{"a":"tavern","t":"Shall we read it together?"},{"a":"sia","t":"...!"},{"a":"tavern","t":"Let's see here... A Kern seal, addressed directly to the Kern emperor?"},{"a":"tavern","t":"My, my. I was dearly hoping for a scandalous love affair, but I suppose treason is fine, too."},{"a":"sia","t":"N-naya, please stop!"},{"a":"tavern","t":"Oh! Here's a juicy bit!"},{"a":"tavern","t":"\"King Reinhold is a complete fool whose presence on the throne benefits you greatly.\""},{"a":"tavern","t":"\"Keeping him alive is sure to damage his kingdom even more so than its ruler's death.\""},{"a":"sia","t":"..."},{"a":"tavern","t":"Such unkind words are rather unbecoming of his advisor, I would say!"},{"a":"sia","t":"Nosy... Naya... You'll pay for this!"},{"a":"tavern","t":"Someday, perhaps. But for now, I believe it is you who will pay. Handsomely, I suspect."},{"a":"sia","t":"...Stooping so low as to blackmail?"},{"a":"tavern","t":"So small a sin, compared to treason!"},{"a":"tavern","t":"If you had planned harm upon our king, on the other hand..."},{"a":"sia","t":"Hmph. Very well. Name your price. And pray that my spy network never outsmarts yours, Naya."},{"a":"tavern","t":"I'm looking forward to it!"}]},{"id":"sia_a","i":4,"title":"The King's Caprice","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fortune Tokens"},"side":true,"lines":[{"a":"sia","t":"My King."},{"a":"king","t":"Dear Sia! How can I help you?"},{"a":"sia","t":"Have you, by any chance, been on another of your \"capricious\" outbursts recently?"},{"a":"king","t":"N-no! Of course not! I would never!"},{"a":"sia","t":"Strange. Our ledgers indicate that Vault #36 is filled to the brim with <c1>Kunai</c1>."},{"a":"sia","t":"I don't need to remind his majesty that this is an excessively rare item."},{"a":"king","t":"I-I'm sure there is a perfectly logi-"},{"a":"sia","t":"Furthermore, many of the kingdom's rarest antiques have been seen in the hands of common folks."},{"a":"sia","t":"Your generosity is commendable..."},{"a":"sia","t":"...But please refrain from distributing priceless artifacts to fund your mood swings."},{"a":"king","t":"Hmph. Very well! From today onwards, I am a changed man!"},{"a":"sia","t":"Thank you for your understanding. I shall take my leave."},{"a":"king","t":"My will remains strong! I have no need for material goods!"},{"a":"king","t":"...This room could use a few <c1>Regal Blades</c1>, doesn't it?"}]},{"id":"sia_05","i":5,"title":"Agent Swan","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"\"... In a drastic turn of events, an attempt was made on King Reinhold's life.\""},{"a":"sia","t":"\"Azuma seems to be behind this attempt. Agent Swan will investigate further.\""},{"a":"king","t":"Sia! What are you doing?"},{"a":"sia","t":"Oh, merely writing a letter, pay it no mind."},{"a":"sia","t":"(My report to the Kern emperor, that is...)"},{"a":"king","t":"Very well! Some foreign dignitaries are awaiting my presence."},{"a":"king","t":"They may be a tad... offended by last time's shopping trip."},{"a":"king","t":"I would very much enjoy your assistance in defusing this situation!"},{"a":"sia","t":"Of course. I'll be there in a moment, my King."},{"a":"sia","t":"Letting the Kern emperor know of this assassination attempt may usher forth dire consequences..."},{"a":"sia","t":"I... need more time to think. This kingdom is... not yet ready to face Kern."},{"a":"sia","t":"For the sake of everyone's safety... I suppose I could omit this detail..."},{"a":"sia","t":"\"All is going as planned. Agent Swan has nothing to report this month.\""}]},{"id":"sia_06","i":6,"title":"Rose and Thorn","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"king","t":"Sia! There is a visitor here for you! Quite the princely fellow, I might add."},{"a":"sia","t":"...Princely, my King? Surely it couldn't be..."},{"a":"donovan","t":"Lady Sia."},{"a":"sia","t":"...Donovan."},{"a":"sia","t":"My King, an urgent matter awaits you at the treasury. I would recommend you see to it immediately."},{"a":"king","t":"Oh, did the latest Pure Gold shipment come in? I can't wait!"},{"a":"donovan","t":"Ever the fool, this king. Isn't he?"},{"a":"sia","t":"What foul wind brings you to Reinhold's kingdom, alchemist?"},{"a":"donovan","t":"Straight to the point as always, Agent Swan."},{"a":"donovan","t":"I am merely on personal leave. With the Kern Emperor's permission of course."},{"a":"donovan","t":"Smelling the flowers, tasting the potions... An alchemist vacation, you could say."},{"a":"sia","t":"And you would come here, of all places?"},{"a":"donovan","t":"This backwards kingdom does appear to have its fair share of skilled alchemists."},{"a":"donovan","t":"...Though if a swan's loyalty is found to be wavering..."},{"a":"sia","t":"You've made your point, Donovan. You may go enjoy your... vacation."},{"a":"donovan","t":"As you wish, Lady Sia. A pleasure, as always."},{"a":"sia","t":"...Another thorn in my side."}]},{"id":"sia_07","i":7,"title":"Stranger of Gold City","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"Donovan? I hope I'm not interrupting any... spying."},{"a":"donovan","t":"Oh! Lady Sia!"},{"a":"donovan","t":"No, not at all! Merely looking around."},{"a":"sia","t":"There is no need to be so secretive. All are welcome within the Lost City of Gold."},{"a":"sia","t":"However, do keep in mind that, as per the Kingdom's law, any and all <c1>Pure Gold</c1> found within belongs to King Reinhold."},{"a":"sia","t":"In exchange, brave adventurers are rewarded for their contributions."},{"a":"donovan","t":"I see. A most... generous ruler."},{"a":"donovan","t":"The <c1>Pure Gold</c1> is then minted into coinage, resulting in a sharp inflation of currency..."},{"a":"sia","t":"Correct. I see you've been intercepting my mail to the Emperor."},{"a":"donovan","t":"I do enjoy being in the know."},{"a":"sia","t":"Since you're here, make yourself useful and carry some <c1>Pure Gold</c1> back to the castle."},{"a":"donovan","t":"Of course. Anything for my lady."},{"a":"sia","t":"Try not to break a nail on the way back, dear Donovan."}]},{"id":"sia_08","i":8,"title":"At Fate's Crossroad","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"tavern","t":"My little Swan has returned! Ever so punctual, as expected of our greatest administrator."},{"a":"sia","t":"I've answered your summon, Nosy Naya. I've a foul mood, so please make it quick."},{"a":"tavern","t":"Prepare to be all the fouler then! I've intercepted a certain alchemist's mail..."},{"a":"tavern","t":"Expedited Magimail, too! You wouldn't believe how hard it is to get your hands on it!"},{"a":"sia","t":"You don't mean..."},{"a":"tavern","t":"Seems to me that this Donovan caught wind of your little game."},{"a":"sia","t":"If you intercepted it, then..."},{"a":"tavern","t":"That's right, it's not going anywhere! If you pay, of course."},{"a":"sia","t":"I... fine. Name your price, Naya. I'll pay it."},{"a":"tavern","t":"I've upped my usual rates. I'm asking a special bounty for this prize."},{"a":"sia","t":"...Very well. I shall-"},{"a":"tavern","t":"Choose a side, Sia. That's my price."},{"a":"sia","t":"..."},{"a":"tavern","t":"Playing both sides is a dangerous web... and it seems you've tangled yourself spectacularly."},{"a":"tavern","t":"Of course, depending on your answer, I may be able to help..."}]},{"id":"sia_09","i":9,"title":"Chain of Treason","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"Dear Donovan. I have a request, if you would."},{"a":"donovan","t":"Oh? Let's hear it then."},{"a":"sia","t":"Go to the Emperor. Tell him Agent Swan is dead. An honorable, tragic death dutifully serving the Empire."},{"a":"donovan","t":"P-pardon me?"},{"a":"sia","t":"I'm quitting, Donovan. Changing side, if you will."},{"a":"sia","t":"And you'll be the one to break the news. And support my story, of course."},{"a":"donovan","t":"P-preposterous! This is high treason! I would never..."},{"a":"sia","t":"I believe you will, Donovan. Unless, of course, you'd like the world to learn the recipe for your elixir of immortality?"},{"a":"donovan","t":"Ah, is that the extent of your bluff, Sia? I've never told anyone of this recipe. There is no way-"},{"a":"sia","t":"What was it again? Wings of a century-old mayfly... water from the Styx...?"},{"a":"donovan","t":"T-this is..."},{"a":"sia","t":"There were so many ingredients... wasn't there also a dash of wine, for the taste?"},{"a":"donovan","t":"S-silence! SILENCE! I do not know by which dark powers you've learned of this..."},{"a":"sia","t":"It would seem you've underestimated my spy network."},{"a":"donovan","t":"...But I will play your little game. This time."},{"a":"sia","t":"Ever the sore loser, are we? I believe my terms are more than generous."},{"a":"sia","t":"What's one little treason in exchange for your life's work?"}]},{"id":"sia_10","i":10,"title":"Posthumous Assist","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"Agent Whisper. It's me."},{"a":"essence","t":"*Yaaawn*... so soon?"},{"a":"sia","t":"Your information was accurate. I commend you for your stellar work."},{"a":"essence","t":"It's... nothing..."},{"a":"sia","t":"Donovan was always a cautious man, but I suppose not much can stop a ghost from peeping!"},{"a":"essence","t":"Totally... "},{"a":"essence","t":"He looked... really pissed..."},{"a":"sia","t":"As agreed, I'll deliver your payment to your grave as an offering."},{"a":"sia","t":"I added a little bonus too. Please go and torment Donovan some more, for a time."},{"a":"essence","t":"I get paid... to do ghost stuff. This is great."}]},{"id":"sia_11","i":11,"title":"A Swan Flies Free","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"king","t":"Sia! I can barely hold back! How much longer until I can unleash my Caprices upon the world!?"},{"a":"sia","t":"It's merely been a few days, your Majesty. Please pace yourself a little longer."},{"a":"king","t":"Ah! What might all this paperwork be about?"},{"a":"sia","t":"Birth certificates and other important administrative documents relating to myself."},{"a":"sia","t":"It seems that, by pure coincidence, much of the documents detailing my life in this kingdom have gone missing."},{"a":"sia","t":"I've thus been dutifully filling these forms from memory."},{"a":"king","t":"Of course! It wouldn't do for my greatest advisor to not be an official subject of my Kingdom!"},{"a":"king","t":"Here! I shall stamp them with my royal seal posthaste!"},{"a":"king","t":"All done! No details escape your gaze, as usual!"},{"a":"sia","t":"Thank you, your Grace. I hope to serve for many decades to come."},{"a":"king","t":"I could hope for nothing less!"},{"a":"king","t":"Sia, is that a tear I spy? Does filing paperwork really fill you with jubilant joy?"},{"a":"sia","t":"Ah... no. In fact, I would say this paperwork has bored me to tears."},{"a":"sia","t":"Now then! Shall we discuss those Caprices of yours?"},{"a":"king","t":"Let's! If you ask me, the current Shield situation..."}]}]},{"id":"atlab_sokka","name":"Sokka","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Great Warrior Sokka","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"atlab_aang","t":"And how about... this!"},{"a":"tavern","t":"Oh, that's a cute trick!"},{"a":"atlab_sokka","t":"Ugh. He does that all the time!"},{"a":"argon","t":"Hi, Sokka right? I'm Argon!"},{"a":"atlab_sokka","t":"Oh, hey. If you want bending tricks, you're looking for Aang."},{"a":"argon","t":"Oh, no. I don't know much about magic. Or bending."},{"a":"argon","t":"Judging from your gear, you looked to be a fearsome warrior."},{"a":"atlab_sokka","t":"F-fearsome warrior?"},{"a":"atlab_sokka","t":"W-well you'd be right! I'm Sokka, the Great Warrior of Team Avatar!"},{"a":"argon","t":"I knew it! You must have some incredible tales to tell!"},{"a":"atlab_sokka","t":"You bet! For example, during the siege of Agna Qel'a..."},{"a":"atlab_sokka","t":"And that's how my girlfriend, at the time, became the moon."},{"a":"argon","t":"T-the moon!?"},{"a":"atlab_sokka","t":"Yeah. But then, the Fire Nation fleet..."},{"a":"atlab_sokka","t":"...and bang! I knocked out that giant owl guy in the library."},{"a":"argon","t":"Wow! Wasn't that owl a powerful spirit?"},{"a":"atlab_sokka","t":"That's right! But Team Avatar is always victorious with Sokka around!"},{"a":"atlab_sokka","t":"...Speaking of that, where's Aang?"},{"a":"argon","t":"Oh, he left about an hour ago."},{"a":"atlab_sokka","t":"Dang! I completely lost track of time. Sorry Argon, gotta run!"}]},{"id":"atlab_sokka_02","i":2,"title":"Great Smith Sokka","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"blacksmith","t":"Hard at work, Sokka?"},{"a":"atlab_sokka","t":"Hey, Wallace. Thanks for letting me use your tools!"},{"a":"blacksmith","t":"No problem! I didn't expect you to be such a craftsman at your age!"},{"a":"atlab_sokka","t":"When you're the only non-bender in the group, you gotta pick up all sorts of skills."},{"a":"atlab_sokka","t":"It's not every day I get to use great tools like these..."},{"a":"atlab_sokka","t":"Maintenance will be done in a flash!"},{"a":"blacksmith","t":"That sword you're sharpening... where did you get that?"},{"a":"atlab_sokka","t":"That's my Space Sword! Forged it myself!"},{"a":"blacksmith","t":"Star Metal? Not bad, kid!"},{"a":"blacksmith","t":"It must be... out of this world!"},{"a":"atlab_sokka","t":"You bet! There's no other sword like it!"},{"a":"polonia","t":"Ahoy! Sorry to interrupt, but any of ye fine lads care to help fix me ship?"},{"a":"polonia","t":"She be right moody today. Hit some weird iron balls and got herself beached..."},{"a":"blacksmith","t":"Sounds like a boatload of trouble!"},{"a":"atlab_sokka","t":"Hey, no problem, I'm Water Tribe! I’ll see what I can do. Sorry Wallace, I gotta go!"},{"a":"blacksmith","t":"I'll repair the rest of your gear in the meantime. Good luck!"}]},{"id":"atlab_sokka_03","i":3,"title":"Great Navigator Sokka","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"atlab_sokka","t":"There, that should get you to port safely, at least."},{"a":"polonia","t":"That's a proper fix. All solid-like!"},{"a":"atlab_sokka","t":"....Your rudder's held together with driftwood and pieces of my shirt."},{"a":"atlab_sokka","t":"I wouldn't say \"solid-like\". More like, Sokka fix."},{"a":"polonia","t":"Yo ho ho! How come a landlubber like ye be fixin' ships, then?"},{"a":"atlab_sokka","t":"Water Tribe life is all about boats and fishing. I was sailing before I could walk."},{"a":"atlab_sokka","t":"Just recently, I even came up with plans for a waterbending-powered submarine!"},{"a":"polonia","t":"Yer speakin' all landlubby. What be that?"},{"a":"atlab_sokka","t":"It's... uh, a metal ship that goes underwater."},{"a":"polonia","t":"Sounds to me like yer sending sea dogs to Davy Jones' Locker in a fancy box."},{"a":"engineer","t":"Did I just hear, \"highly dangerous, untested prototype\"?"},{"a":"atlab_sokka","t":"Ah... not quite-"},{"a":"engineer","t":"I like your style. Come with me, new guy."},{"a":"polonia","t":"Yo ho ho, back to sea! Anchors aweigh, before the bounty hunters get here!"},{"a":"polonia","t":"Arr, better dodge the floaty iron balls this time."}]},{"id":"atlab_sokka_04","i":4,"title":"Great Inventor Sokka","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"engineer","t":"Fascinating! Not gonna lie, your blueprint's a bit shoddy..."},{"a":"engineer","t":"...But with a bit of elbow grease, I think that submarine can work!"},{"a":"atlab_sokka","t":"Genius, right? I knew it!"},{"a":"atlab_sokka","t":"Though keep in mind it's designed to be operated by Waterbenders."},{"a":"engineer","t":"Details, details. We'll figure something out."},{"a":"engineer","t":"Just think! With this, we could explore the Sunken Temple!"},{"a":"atlab_sokka","t":"Oh, and it doesn't hold a lot of air, so keep the trips short."},{"a":"atlab_sokka","t":"...Are you listening?"},{"a":"engineer","t":"Don't lean on that large iron ball."},{"a":"atlab_sokka","t":"...Huh? Woah! Why not?"},{"a":"engineer","t":"My prototype sea bomb. Don't touch it. Very explody."},{"a":"atlab_sokka","t":"...Oh."},{"a":"atlab_sokka","t":"Well anyway, let me know how the prototype goes."},{"a":"atlab_sokka","t":"If it works... we have a use for them in the future."}]}]},{"id":"leather","name":"Tamas","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Hey dude. I think I'm done being a Champion."},{"a":"leather","t":"It's a lot more responsibilities than I thought, dude. I barely have time for my leather!"},{"a":"leather","t":"Maybe I'll try again next year, dude. See you in town!"}]},{"id":"leather_01","i":1,"title":"Leather and the Tree","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"leather","t":"Thanks for the help, dude."},{"a":"argon","t":"No problem, Tamas! That's a lot of leather!"},{"a":"leather","t":"Got a big haul today. Mind your step, though."},{"a":"argon","t":"Yeah... it's bumpy around here... Woah!"},{"a":"leather","t":"Woah! Ow!"},{"a":"argon","t":"Sorry, Tamas! Are you OK?"},{"a":"leather","t":"Bumped my head a bit, dude. I think I'm fine."},{"a":"leather","t":"...I just got a flash of genius, dude."},{"a":"leather","t":"Gotta go, dude. This is big."},{"a":"argon","t":"Uh, sure! Glad to help!"},{"a":"argon","t":"...But what do I do with all this scattered leather...?"}]},{"id":"leather_02","i":2,"title":"Foretold by Prophecy","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"leather","t":"...and that's how I hit my head, dude. Got a small bump here."},{"a":"mana","t":"This one listens, but assist it can not."},{"a":"mana","t":"The flows of ether divine and reveal, but they do not heal."},{"a":"leather","t":"It's still magic, right? C'mon dude, just touch it with your magic hands."},{"a":"mana","t":"There is no-"},{"a":"mana","t":"...!!!"},{"a":"mana","t":"This... destiny...! Overwhelming...!"},{"a":"leather","t":"You sure that worked, dude? I'm still feeling a bit dizzy."},{"a":"mana","t":"...Apologies. A new vision arose that requires meditation."},{"a":"mana","t":"Seek the Goddess' Favored for your... wounds. This one must depart at once."},{"a":"leather","t":"Aight dude. Guess I'll just walk it off, feeling pretty strong lately."}]},{"id":"leather_03","i":3,"title":"The Champion Union","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"argon","t":"So there's a new, uh, Champion in town."},{"a":"polonia","t":"Yo ho ho! Me hopes he's a stud!"},{"a":"leather","t":"Hey dudes."},{"a":"polonia","t":"Blasted barnacles! Are ye kiddin' me?"},{"a":"lilu","t":"Tamas!? When did you..."},{"a":"leather","t":"Decided to give this Champion business a shot, dude. Doesn't look too hard."},{"a":"argon","t":"Um... Tamas, why don't you tell us what you do?"},{"a":"leather","t":"I give monsters a whack, dude. I can also sniff out leather items for miles."},{"a":"polonia","t":"Hoy! Stealin' stuff is ME shtick! Find yer own!"},{"a":"leather","t":"It's not stealing, dude. People just leave them all over the place."},{"a":"lilu","t":"Things are about to get pretty interesting around here!"},{"a":"polonia","t":"Arr, ye may be right..."}]},{"id":"leather_04","i":4,"title":"Unsung Hero","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fortune Tokens"},"side":false,"lines":[{"a":"sia","t":"My King, I have a most unusual report."},{"a":"king","t":"I am all ears, as always! Go right on!"},{"a":"sia","t":"Heroes and caravans report that roads are safer than ever."},{"a":"sia","t":"Monsters make themselves scarce, and even appear too afraid to attack anyone."},{"a":"king","t":"Splendid news!"},{"a":"sia","t":"However, we cannot think of any reason behind this strange behavior."},{"a":"sia","t":"Equally strange is a sudden crash in the market for Leather goods..."},{"a":"king","t":"A coincidence, I am sure! Let us feast and celebrate these good news!"},{"a":"sia","t":"Perhaps, my King... perhaps."}]}]},{"id":"yami","name":"Yami","chapters":[{"id":"yami_01","i":1,"title":"The Azuman Wanderer","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Hee hee hee! What do we have here?"},{"a":"yami","t":"Hmph. Begone, pest."},{"a":"monster_forest_Boss","t":"Y'got some bad manners, lady! And weird clothes!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Ah hah! You smell like Azuma, the eastern human kingdom!"},{"a":"monster_forest_Boss","t":"What're ya doing all the way over here, lady?"},{"a":"monster_forest_Boss","t":"Armed to the teeth and tight lipped... Ya gotta be an assassin, right?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Hee hee! I knew it! Stupid humans, always killing each others!"},{"a":"yami","t":"...You're right. I traveled here to kill a tyrannical king."},{"a":"monster_forest_Boss","t":"Well! Ya can't be a good assassin if you just tell everybody that! Why'd you tell me?"},{"a":"yami","t":"Because you won't live to tell anybody. Farewell."},{"a":"monster_forest_Boss","t":"Eek!"},{"a":"yami","t":"...King Reinhold, you're next."}]},{"id":"yami_02","i":2,"title":"Hunt or be Hunted","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"yami","t":"...The castle's security is tight."},{"a":"yami","t":"A password system that changes daily..."},{"a":"yami","t":"Unscheduled guard patrols..."},{"a":"yami","t":"I'll need to be-"},{"a":"argon","t":"Hi there! You, in the bushes!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Are you here to become a knight too?"},{"a":"argon","t":"Sia will be here soon! There's no need to hide, she's pretty nice!"},{"a":"yami","t":"Sia...!"},{"a":"yami","t":"I need to leave. Farewell."},{"a":"argon","t":"W-wait!"},{"a":"argon","t":"Woah! Smoke bomb!?"},{"a":"yami","t":"...I lost that fool."},{"a":"yami","t":"With Sia here... my task will be difficult."},{"a":"yami","t":"But it must be done. I cannot fail."},{"a":"yami","t":"For the Order... and for my sister's sake."}]},{"id":"yami_03","i":3,"title":"Turning Point","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"king","t":"Esteemed people of my kingdom! Thank you for coming to my sumptuous feast!"},{"a":"king","t":"It is also a perfect opportunity for you all to gaze upon my beautiful self! Do not miss this chance!"},{"a":"yami","t":"(Pompous tyrant. Typical.)"},{"a":"sia","t":"Erm, yes. Thank you for this edifying speech, your Majesty."},{"a":"sia","t":"We have gathered you here today to celebrate the King's incredible generosity."},{"a":"sia","t":"In the past months, he has donated several million gold from his own coffers..."},{"a":"sia","t":"...to several local temples, schools and orphanages."},{"a":"sia","t":"All are welcome to partake, so please tell your friends and family."},{"a":"sia","t":"Long live King Reinhold!"},{"a":"yami","t":"(...These are not the actions of a tyrant.)"},{"a":"yami","t":"(...No, the Order wouldn't lie. This must be a trick.)"},{"a":"yami","t":"Tyrant Reinhold, your reign ends now!"},{"a":"sia","t":"A shuriken...! The Azuman assassin!"},{"a":"yami","t":"I missed...!? Impossible!"},{"a":"sia","t":"Guards! Block off all exits! Capture this woman at once!"}]},{"id":"yami_04","i":4,"title":"Reflection","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"yami","t":"(I hesitated... And failed.)"},{"a":"yami","t":"(Could the Order have lied...?)"},{"a":"yami","t":"(It matters not. I am on my own, now.)"},{"a":"argon","t":"I finally found you!"},{"a":"yami","t":"The foolish knight!"},{"a":"argon","t":"Woah! I'm not here to fight!"},{"a":"yami","t":"I won't fall for your tricks, Reinhold dog!"},{"a":"argon","t":"...You missed on purpose didn't you?"},{"a":"yami","t":"...!"},{"a":"argon","t":"I saw you at the feast. It even looked like you regretted throwing that shuriken."},{"a":"argon","t":"The King's not a bad person, you know? He's a bit weird sometimes, but he tries his best!"},{"a":"argon","t":"I'm not sure who paid you to do this, but they can't be good guys..."},{"a":"argon","t":"How about going back to the castle and apologizing? I'm sure Reinhold will-"},{"a":"yami","t":"...Apologize? How dense."},{"a":"yami","t":"I have a lot of thinking to do. Don't follow me, if you value your life."},{"a":"argon","t":"...She's not a bad person, I'm sure of it."},{"a":"argon","t":"Now I need to report to Sia..."},{"a":"argon","t":"Oh man, I'm going to get chewed out..."}]},{"id":"yami_05","i":5,"title":"By the Moonlight","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Sunlight in the willows high, radiance of ages past<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>Of the Elven glade, we- Eek!"},{"a":"yami","t":"The cold sting you feel is my blade to your neck."},{"a":"yami","t":"I have questions. If your answers are honest, I may let you live."},{"a":"fabric","t":"Aaah! Y-yes! Anyth- Ow!"},{"a":"yami","t":"Silence."},{"a":"yami","t":"The fool you call king... Tell me about him."},{"a":"fabric","t":"K-King Reinhold? He is the ruler of these lands..."},{"a":"fabric","t":"Though he is rather eccentric, there is no denying his virtue and generosity."},{"a":"fabric","t":"...What he lacks in experience, his newest advisor, Sia, more than makes up for it!"},{"a":"yami","t":"Impossible...! Your words reek of cowardice, but they ring true."},{"a":"yami","t":"This city! Does it host an oracle?"},{"a":"fabric","t":"Ah! Yes! The elf, Serene, up on the hill!"},{"a":"fabric","t":"Mysterious stranger... May I have the honor of knowing your na- Ow!"},{"a":"yami","t":"A few days earlier, I would not have thought twice about killing you. Do not squander your luck."},{"a":"yami","t":"Return to your vapid life and forget about everything that has transpired here."},{"a":"fabric","t":"...Whew! What an exhilarating encounter!"},{"a":"fabric","t":"Black-clad maiden... Will we ever meet again, I wonder...?"}]},{"id":"yami_06","i":6,"title":"Broken Pawn","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"mana","t":"...A black wind betrays the Stalker's presence."},{"a":"yami","t":"...! How...?"},{"a":"mana","t":"She Who Stalks steps as a feather, but a heavy heart is laid bare to the third eye."},{"a":"yami","t":"...Enough charades, oracle. I need answers."},{"a":"yami","t":"About the Order... My family."},{"a":"mana","t":"A dealer in death comes demanding guidance. What does it offer in return?"},{"a":"yami","t":"Your life."},{"a":"mana","t":"...So be it."},{"a":"mana","t":"<c1>The Azuman Order, once concerned with righting wrongs...</c1>"},{"a":"mana","t":"<c1>...Champions of order, turned slaves to the highest bidder...</c1>"},{"a":"mana","t":"<c1>...For an insurmountable task, a pawn is sacrificed...</c1>"},{"a":"mana","t":"<c1>...In failure or success both, The Order emerges a victor.</c1>"},{"a":"yami","t":"...Impossible."},{"a":"mana","t":"The messenger has spoken."},{"a":"yami","t":"...IMPOSSIBLE!"},{"a":"mana","t":"..."},{"a":"mana","t":"One who stalks the shadows must also make amends with light, given time."}]},{"id":"yami_07","i":7,"title":"Fight or Flight","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"yami","t":"...I'll need to gather my things and leave as soon as possible."},{"a":"inn","t":"Hey there, mysterious stranger."},{"a":"yami","t":"Innkeeper. I've paid extra for your silence."},{"a":"inn","t":"No need to worry, we don't pry here at the Emerald Inn!"},{"a":"inn","t":"That being said, we have some mean-looking visitors who seemed to be looking for you."},{"a":"yami","t":"(Enforcers from the Order? So soon?)"},{"a":"inn","t":"They didn't leave a name. Real shady folks. Friends of yours?"},{"a":"yami","t":"Not anymore. Tell them I'm dead. I may as well be."},{"a":"inn","t":"Leaving in a rush, eh? I figured you might. I prepared some supplies for you."},{"a":"yami","t":"...Thank you innkeeper. But I won't need them where I'm going."}]},{"id":"yami_08","i":8,"title":"One Way Trip","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"To Bleakspire Peaks, you say?"},{"a":"wood","t":"Yeah, I saw a ninja-looking girl matching your description. She looked to be in a rush."},{"a":"sia","t":"Excellent. We've finally tracked down our assassin."},{"a":"sia","t":"I'll assemble a patrol and..."},{"a":"wood","t":"You sure about that? I don't think that's necessary."},{"a":"sia","t":"...Why not, Gorza?"},{"a":"wood","t":"A solo expedition to Bleakspire Peaks is suicide. That girl wasn't packing any supplies, either."},{"a":"wood","t":"There's no way she doesn't know that. Even Rudo's not stupid enough to go there alone."},{"a":"sia","t":"Is that so? Thank you Gorza, I'll take it into consideration."},{"a":"sia","t":"I suppose this problem solves itself, but..."},{"a":"sia","t":"...It leaves a bitter aftertaste. What are you thinking, assassin?"}]},{"id":"yami_09","i":9,"title":"Bleakspire Clash (Yami)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"argon","t":"This must be fate. A bounty even greater than a Harpy!"},{"a":"yami","t":"...Bring it on. I'll kill you where you stand."},{"a":"argon","t":"You say that, but you don't sound very convinced..."},{"a":"yami","t":"...You're right. I don't care about anything anymore."},{"a":"yami","t":"If you truly want me dead, then leave me to die here."},{"a":"argon","t":"I would never leave someone to die! I'll take you back to King Reinhold!"},{"a":"argon","t":"I know he'll understand! I'll carry you back if I have to!"},{"a":"yami","t":"..."},{"a":"argon","t":"Come on, hup!"},{"a":"argon","t":"Hold on, you're all skin and bones! When did you last eat?"},{"a":"yami","t":"..."},{"a":"argon","t":"Have some snacks on the way back, it's going to be a bumpy ride!"}]},{"id":"yami_10","i":10,"title":"Behind Enemy Lines","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"Guards! Bring reinforcements and watch her every move!"},{"a":"sia","t":"Argon, please wait outside while we discuss with this... intruder."},{"a":"argon","t":"At once!"},{"a":"sia","t":"Now then. Speak, assassin."},{"a":"yami","t":"Hmph, that's right. I was hired to assassinate a tyrant."},{"a":"yami","t":"Or so I thought. It seems he is merely a well-meaning buffoon."},{"a":"king","t":"B-buffoon!?"},{"a":"sia","t":"What does your people have against our King?"},{"a":"yami","t":"My order strikes only in the name of justice..."},{"a":"yami","t":"But it seems that was a lie. And with my failure, I will be hunted, as well."},{"a":"yami","t":"I... apologize. I will submit to righteous... punishment..."},{"a":"yami","t":"...Ugh."},{"a":"king","t":"She collapsed!"},{"a":"sia","t":"Exhausted and starved..."},{"a":"sia","t":"Guards! Summon our best physicians at her bedside!"},{"a":"sia","t":"Treat her with respect fitting for a royal guest."}]},{"id":"yami_epilogue","i":11,"title":"Epilogue","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Jewels"},"side":false,"lines":[{"a":"sia","t":"Uff... Uff... Reaching you is... quite the climb..."},{"a":"yami","t":"This is my home now."},{"a":"sia","t":"Why not take up residence inside the city? You've been pardoned."},{"a":"yami","t":"My clan most likely believes me dead. I would rather keep it as such."},{"a":"sia","t":"I understand. I'll see that you are supplied regularly."},{"a":"sia","t":"Now then, as for your next task..."},{"a":"yami","t":"More goons from the Empire?"},{"a":"sia","t":"That's correct. As you know, his Majesty draw much ire from envious eyes."},{"a":"sia","t":"Consult this document for more information on your targets."},{"a":"yami","t":"It will be done."},{"a":"sia","t":"It pains me to say it, but I believe you."},{"a":"sia","t":"I should be heading back. Though I'm not looking forward to the trip..."},{"a":"yami","t":"Sia... Reinhold..."},{"a":"yami","t":"...Thank you. Sincerely."}]}]}];
